class AuriaApp(ctk.CTk):
    def __init__(self):
        super().__init__()
        self.title("Auria v0.1")
        # Ícone da janela (barra de título + taskbar)
        try:
            import base64 as _b64ico
            from PIL import Image, ImageTk
            from io import BytesIO as _BIO
            _ico_pil = Image.open(_BIO(_b64ico.b64decode(_LOGO_SYM_B64.strip()))).convert("RGBA")
            # Gera múltiplos tamanhos para melhor qualidade em diferentes DPIs
            _ico_32  = _ico_pil.resize((32, 32), Image.LANCZOS)
            _ico_64  = _ico_pil.resize((64, 64), Image.LANCZOS)
            _ico_ph  = ImageTk.PhotoImage(_ico_64)
            self.iconphoto(True, _ico_ph)
            self._iconphoto_ref = _ico_ph  # evita garbage-collection
        except Exception as _e:
            pass  # sem ícone se PIL não disponível
        self.geometry("1280x820")  # tamanho inicial; maximizado após splash
        ctk.set_appearance_mode("System")
        ctk.set_default_color_theme("blue")
        self.grid_rowconfigure(0, weight=1)
        self.grid_columnconfigure(0, weight=0)
        self.grid_columnconfigure(1, weight=0)
        self.grid_columnconfigure(2, weight=1)
        self.protocol("WM_DELETE_WINDOW", self.on_closing)
        self.unsaved_changes = False
        self.opcoes_disciplina = ["Arquitetura","Estrutura","Elétrica","Hidráulica",
                                   "HVAC","Topografia","Incêndio","Coordenação"]
        self.tipos_apontamento = [
            "Interferência entre Disciplinas","Falha Gráfica / Modelagem","Dúvida",
            "Não atendimento à Diretrizes e Normas","Ausência de Informação / Detalhe",
            "Melhoria / Otimização","Problema Construtivo"
        ]
        self.arquivo_ctb   = "ctb_padrao.json"
        self.arquivo_config= "auria_config.json"
        _init_fonts()  # cria fontes globais reutilizáveis
        self.carregar_ctb_local()
        self.carregar_config()
        self.reset_sessao()
        self.prancha_bloqueada = True
        self.modo_arrastar    = False   # arrasta camada ativa sobre as demais
        self.drag_start_x     = 0
        self.drag_start_y     = 0
        # Offset de posicionamento por camada (dx, dy) em pixels na resolução base
        self._layer_offset    = {}      # {camada_id: (dx_norm, dy_norm)} 0-1 frações
        self._layer_scale     = {}      # {camada_id: float} escala relativa
        self._render_pending  = None    # after() id para debounce de zoom
        self._drag_active     = False   # True durante arraste (usa preview baixa res)
        self._img_cache       = OrderedDict()  # LRU cache de imagens
        self._cache_lock      = threading.Lock()  # protege _img_cache
        self.tamanho_pin      = 13
        # Esconde janela principal durante splash
        self.withdraw()
        self.after(100, self._mostrar_splash)

    # ── ESTADO DA SESSÃO ─────────────────────────────────────────────────────

    def reset_sessao(self):
        self.meta_empreendimento = self.config_app.get('empreendimento','')
        self.meta_analista       = self.config_app.get('analista','')
        self.meta_etapa          = self.config_app.get('etapa','Projeto Executivo')
        self.meta_tipo_analise   = ""
        self.arquivos_input_data = []

        # ── Camadas PDF ───────────────────────────────────────────────────────
        # Cada camada: {path, pil_original, width_pts, height_pts,
        #               opacity, color_mode, visible, disc_name, n_pages, page_num}
        self.camadas_pdf   = {}
        self.camadas_ids   = []
        self.ordem_renderizacao = []
        self.nomes_arquivos     = {}
        self.mapa_arquivos      = {}
        self.caminhos_arquivos  = {}
        self.camada_fundo_id    = None
        self.disciplina_ativa   = None

        # ── Renderização ──────────────────────────────────────────────────────
        self._render_zoom  = 1.0    # fator de zoom atual
        self._base_w       = 0      # largura da imagem base (pixels @ BASE_DPI)
        self._base_h       = 0
        self._canvas_photo = None   # ImageTk.PhotoImage atual
        self._canvas_img_id= None   # ID do item de imagem no canvas
        self._drag_start   = None   # para pan com botão 2

        # ── Issues / Apontamentos ─────────────────────────────────────────────
        if not hasattr(self, '_issues_lock'):
            self._issues_lock = threading.RLock()
        self.lista_issues         = []
        self.contadores_disciplina= {d: 1 for d in self.opcoes_disciplina}
        self.contadores_disciplina["GER"] = 1
        self.issue_em_edicao      = None
        self.modo_multi_pin       = False
        self.janela_issue_ativa   = None
        self._barra_minimizados   = None
        self.unsaved_changes      = False
        self.logs_analise_ia = {}   # {disc_name: [{'titulo','desc','prio','tipo'}]}
        # ── Empreendimento ────────────────────────────────────────────────────
        # _emp_config NÃO é resetado aqui — é carregado de empreendimento_config.json
        # em carregar_config() e deve persistir entre sessões
        if not hasattr(self, "_emp_config"): self._emp_config = {}
        self._undo_stack  = []   # lista de snapshots de lista_issues
        self._redo_stack  = []
        # ── Trena / Cotas ──────────────────────────────────────────────────────
        self._trena_calibrada   = False     # se já foi calibrada
        # ── Snap ──────────────────────────────────────────────────────────────
        self._snap_enabled  = False  # desativado por padrão; ativar na trena
        self._snap_radius   = 12
        self._snap_cache    = {}
        self._snap_indicator= None
        self._trena_px_por_m    = 1.0       # pixels (@ zoom=1) por metro
        self._trena_modo        = None      # 'calibrar' | 'medir' | None
        self._trena_start       = None      # (cx,cy) ponto inicial
        self._cotas             = []        # [{id,cx1,cy1,cx2,cy2,metros,label,visible}]
        self._cota_id_counter   = 1
        self.filtros_ativos = {
            'texto':'',
            'status':set(),'disciplina':set(),
            'criticidade':set(),'tipo':set(),
            'data_criacao_inicio':'','data_criacao_fim':'',
            'data_resolucao_inicio':'','data_resolucao_fim':''
        }

        # ── Desenhos sobre prancha ────────────────────────────────────────────
        self._draw_mode_active    = False
        self._active_draw_session = None

        # ── Compatibilidade com métodos de desenho (coords normalizadas) ──────
        # canvas_to_dxf / dxf_to_canvas agora convertem de/para (nx, ny) 0-1
        # Os specs de desenho continuam usando 'pts_dxf' internamente
        # mas armazenam (nx, ny) em vez de coordenadas DXF reais
        self._cam_transform = {}   # mantido para compatibilidade (não usado no motor PDF)

    def on_closing(self):
        if self.unsaved_changes:
            r = messagebox.askyesnocancel("Atenção",
                "Existem alterações não salvas.\nDeseja salvar antes de sair?",parent=self)
            if r is True:
                if self.salvar_analise(): self.destroy()
            elif r is False:
                self.destroy()
        else:
            self.destroy()

    def marcar_alterado(self): self.unsaved_changes = True

    def img_to_b64(self, img):
        b = BytesIO(); img.save(b, format="PNG")
        return base64.b64encode(b.getvalue()).decode("utf-8")

    def b64_to_img(self, b64):
        return Image.open(BytesIO(base64.b64decode(b64)))

    def strip_emoji_prio(self, p):
        s = p.replace("🔴 ","").replace("🟠 ","").replace("🟡 ","")
        # Map old labels to new for backward compat
        MAP = {"Crítica":"Severa / Imediata",
               "Média":"Importante / Programada",
               "Observação":"Observação / Atenção"}
        return MAP.get(s, s)

    def resolver_cor_pino(self, prioridade):
        p = self.strip_emoji_prio(prioridade)
        if "Severa / Imediata"    in p: return "#E74C3C"
        if "Importante / Programada"      in p: return "#F39C12"
        if "Observação" in p: return "#F1C40F"
        return "#E74C3C"

    # ── CONFIGURAÇÃO ─────────────────────────────────────────────────────────

    def carregar_config(self):
        self.config_app = {'empreendimento':'','analista':'',
                           'etapa':'Projeto Executivo','emails_disciplina':{}}
        self._emp_config = {}   # garante que existe antes de tentar carregar
        # Carrega config de empreendimento
        if os.path.exists('empreendimento_config.json'):
            try:
                with open('empreendimento_config.json','r',encoding='utf-8') as f:
                    self._emp_config = json.load(f)
            except (json.JSONDecodeError, OSError) as e:
                print(f"[Config] Erro ao carregar empreendimento_config: {e}")
        # Tenta carregar config atual; se não existe, tenta o nome legado (migração automática)
        _cfg_files = [self.arquivo_config, "proj_config.json"]
        for _cfg_path in _cfg_files:
            if os.path.exists(_cfg_path):
                try:
                    with open(_cfg_path, 'r', encoding='utf-8') as f:
                        self.config_app.update(json.load(f))
                    # Restaura chave API se salva
                    if self.config_app.get('groq_api_key'):
                        global _GROQ_API_KEY
                        _GROQ_API_KEY = self.config_app['groq_api_key']
                    # Migra para novo nome se estava no legado
                    if _cfg_path != self.arquivo_config:
                        try:
                            with open(self.arquivo_config, 'w') as f:
                                json.dump(self.config_app, f, ensure_ascii=False)
                        except OSError as e:
                            print(f"[Config] Erro migração: {e}")
                except (json.JSONDecodeError, OSError) as e:
                    print(f"[Config] Erro ao carregar {_cfg_path}: {e}")
                break  # usou o primeiro arquivo encontrado

    def salvar_config(self):
        try:
            with open(self.arquivo_config,'w',encoding='utf-8') as f:
                json.dump(self.config_app, f, ensure_ascii=False)
        except OSError as e:
            print(f"[Config] Erro ao salvar: {e}")

    def carregar_ctb_local(self):
        self.config_penas = {1:1,2:1,3:3,4:2,5:1,6:2,7:1}
        if os.path.exists(self.arquivo_ctb):
            try:
                with open(self.arquivo_ctb,'r') as f:
                    self.config_penas = {int(k):v for k,v in json.load(f).items()}
            except (json.JSONDecodeError, OSError, ValueError) as e:
                print(f"[Config] Erro ao carregar CTB: {e}")

    def salvar_ctb_local(self):
        try:
            with open(self.arquivo_ctb,'w') as f:
                json.dump(self.config_penas, f)
        except OSError as e:
            print(f"[Config] Erro ao salvar CTB: {e}")

    # ── MENUS SUPERIORES ─────────────────────────────────────────────────────

    def montar_infraestrutura_menu_superior(self):
        self.barra_menu_superior = ctk.CTkFrame(self, height=30, corner_radius=0,
                                                 fg_color=("gray90","gray15"))
        sb = {"fg_color":"transparent","text_color":("black","white"),
              "hover_color":("gray80","gray25"),"corner_radius":4,
              "width":60,"height":28,"font":ctk.CTkFont(size=12)}
        ba = ctk.CTkButton(self.barra_menu_superior, text="Arquivo", **sb)
        ba.pack(side="left", padx=(10,2), pady=3)
        ba.bind("<Button-1>", self.popup_arquivo)
        bl = ctk.CTkButton(self.barra_menu_superior, text="Análise", **sb)
        bl.pack(side="left", padx=2, pady=3)
        bl.bind("<Button-1>", self.popup_analise)
        bh = ctk.CTkButton(self.barra_menu_superior, text="Ajuda", **sb)
        bh.pack(side="left", padx=2, pady=3)
        bh.bind("<Button-1>", self.popup_ajuda)
        ctk.CTkLabel(self.barra_menu_superior,
                     text="Auria v0.1",
                     font=ctk.CTkFont(size=11, slant="italic"),
                     text_color="gray").pack(side="right", padx=15)

    def popup_arquivo(self, event):
        m = tk.Menu(self, tearoff=0, font=("Segoe UI",10))
        m.add_command(label="📄 Nova Análise...",  command=self.nova_analise)
        m.add_separator()
        m.add_command(label="📂 Abrir Análise...", command=self.abrir_analise)
        m.add_command(label="💾 Salvar Análise",   command=self.salvar_analise)
        m.add_separator()
        m.add_command(label="📤 Exportar Relatórios", command=self.abrir_menu_exportar)
        m.add_command(label="📌 Exportar PDF Anotado", command=self.exportar_pdf_anotado)
