        self._entry_busca.pack(fill="x", padx=10, pady=(0,4))
        self.frame_issues_lateral = ctk.CTkScrollableFrame(
            self.sidebar_frame, fg_color=("gray90","gray15"), corner_radius=5)
        self.frame_issues_lateral.pack(fill="both", expand=True, padx=10, pady=5)

        # ── Tema ──────────────────────────────────────────────────────────────
        ft = ctk.CTkFrame(self.sidebar_frame, fg_color="transparent")
