    def abrir_painel_bi(self):
        """Painel BI completo de apontamentos com gráficos, filtros e tabela."""
        import math
        from datetime import datetime as _dt

        # ── Janela principal (CTkToplevel padrão — CTkScrollableFrame funciona melhor) ──
        jp = ctk.CTkToplevel(self)
        jp.title("📊 Painel de Apontamentos — Auria")
        self._centrar_janela(jp, 980, 720)
        jp.resizable(True, True)
        jp.attributes("-topmost", True)
        jp.lift()
        jp.focus_force()
        jc = jp   # conteúdo direto na janela

        # ── Estado de filtros do painel (multi-select) ───────────────────────
        # _mf é definido mais abaixo junto com os botões de filtro

        def _mf_ativos(key):
            """Retorna set de opções ativas para um filtro multi-select."""
            return {o for o, v in _mf.get(key, {}).items() if v}

        def _issues_filtrados():
            from datetime import datetime as _dti
            out = []
            sel_disc = _mf_ativos("disciplina")
            sel_stat = _mf_ativos("status")
            sel_crit = _mf_ativos("criticidade")
            sel_tipo = _mf_ativos("tipo")
            sel_etap = _mf_ativos("etapa")
            sel_loc  = _mf_ativos("local")
            for iss in self.lista_issues:
                if sel_disc and iss.get('disciplina') not in sel_disc: continue
                if sel_stat and iss.get('status') not in sel_stat: continue
                if sel_crit:
                    if self.strip_emoji_prio(iss.get('prioridade','')) not in sel_crit: continue
                if sel_tipo and iss.get('tipo') not in sel_tipo: continue
                if sel_etap and iss.get('etapa') not in sel_etap: continue
                if sel_loc:
                    loc = iss.get('local', '')
                    locs = set(loc if isinstance(loc, list) else ([loc] if loc else []))
                    if not sel_loc & locs: continue
                # Filtro de período pela data de criação
                if _periodo["de"]:
                    try:
                        dcr = _dti.strptime(iss.get('data_criacao',''), "%d/%m/%Y")
                        ate = _periodo["ate"] or _periodo["de"]
                        ate_end = ate.replace(hour=23, minute=59, second=59)
                        if not (_periodo["de"] <= dcr <= ate_end): continue
                    except: pass
                out.append(iss)
            return out

        def _is_atrasado(iss):
            if iss.get('status') == 'Resolvido': return False
            for p in iss.get('participantes', {}).values():
                if self.check_is_atrasado(p.get('prazo',''), p.get('conclusao','')): return True
            return False

        def _dias_atraso(iss):
            """Retorna o maior atraso em dias entre os participantes."""
            mx = 0
            for p in iss.get('participantes', {}).values():
                prazo = p.get('prazo','')
                conc  = p.get('conclusao','')
                if conc.strip(): continue
                try:
                    d = (_dt.now().replace(hour=0,minute=0,second=0,microsecond=0)
                         - _dt.strptime(prazo, "%d/%m/%Y")).days
                    if d > mx: mx = d
                except: pass
            return mx

        # ── Layout: topo (filtros) + meio (KPIs + gráficos) + baixo (tabela) ──
        # Scroll geral
        scroll_root = ctk.CTkScrollableFrame(jc, fg_color="transparent")
        scroll_root.pack(fill="both", expand=True)

        # ── CABEÇALHO ────────────────────────────────────────────────────────
        hdr = ctk.CTkFrame(scroll_root, fg_color=("#1A5276","#0E2F44"), corner_radius=10)
        hdr.pack(fill="x", padx=12, pady=(10,6), ipadx=10, ipady=8)
        hdr_l = ctk.CTkFrame(hdr, fg_color="transparent"); hdr_l.pack(side="left", fill="x", expand=True)
        ctk.CTkLabel(hdr_l, text="📊  Painel de Apontamentos",
                     font=ctk.CTkFont(size=17, weight="bold"),
                     text_color="white").pack(anchor="w")
        ctk.CTkLabel(hdr_l,
                     text=f"{self.meta_empreendimento}  ·  {self.meta_etapa}",
                     text_color="#AED6F1", font=ctk.CTkFont(size=10)).pack(anchor="w")
        # Botão atualizar
        ctk.CTkButton(hdr, text="↺ Atualizar", width=90, height=28,
                      fg_color="#27AE60", hover_color="#1E8449",
                      font=ctk.CTkFont(size=10, weight="bold"),
                      command=lambda: _rebuild()).pack(side="right", padx=8)
        ctk.CTkButton(hdr, text="⬇ Exportar", width=90, height=28,
                      fg_color="#8E44AD", hover_color="#6C3483",
                      font=ctk.CTkFont(size=10, weight="bold"),
                      command=self._exportar_apontamentos_csv
                      ).pack(side="right", padx=(0,4))

        # ── FILTROS ───────────────────────────────────────────────────────────
        ff = ctk.CTkFrame(scroll_root, fg_color=("gray90","gray18"), corner_radius=8)
        ff.pack(fill="x", padx=12, pady=(0,6), ipadx=8, ipady=6)
        ctk.CTkLabel(ff, text="Filtros:", font=ctk.CTkFont(size=10, weight="bold"),
                     text_color="gray").pack(side="left", padx=(4,8))

        discs    = ['Todas'] + sorted({i.get('disciplina','') for i in self.lista_issues if i.get('disciplina')})
        statuses = ['Todos', 'Em aberto', 'Resolvido', 'Reprovados']
        crits    = ['Todas', 'Severa / Imediata', 'Importante / Programada', 'Observação / Atenção']
        tipos_f  = ['Todos'] + self.tipos_apontamento
        etapas_f = ['Todas'] + self._get_etapas()
        locais_f = ['Todos'] + self._get_locais_nomes()

        # ── Multi-select: cada filtro é um dict {opção: bool} ───────────────
        _mf = {
            "disciplina":  {},
            "status":      {},
            "criticidade": {},
            "tipo":        {},
            "etapa":       {},
            "local":       {},
        }
        # Tags frame — linha abaixo da barra de botões
        tags_bar = ctk.CTkFrame(scroll_root, fg_color="transparent")
        tags_bar.pack(fill="x", padx=12, pady=(0,4))

        def _rebuild_tags_bar():
            for w in tags_bar.winfo_children(): w.destroy()
            has_any = False
            CORES_FILTRO = {
                "disciplina":  "#2980B9",
                "status":      "#27AE60",
                "criticidade": "#E74C3C",
                "tipo":        "#8E44AD",
                "etapa":       "#E67E22",
                "local":       "#16A085",
            }
            LABELS_FILTRO = {
                "disciplina":"Disc","status":"Status","criticidade":"Crit",
                "tipo":"Tipo","etapa":"Etapa","local":"Local"
            }
            for key, sels in _mf.items():
                for opt, ativo in sels.items():
                    if not ativo: continue
                    has_any = True
                    cor = CORES_FILTRO.get(key, "#2980B9")
                    tag_f = ctk.CTkFrame(tags_bar, fg_color=cor, corner_radius=12)
                    tag_f.pack(side="left", padx=2, pady=2)
                    ctk.CTkLabel(tag_f,
                                 text=f"{LABELS_FILTRO.get(key,key)}: {opt[:20]}",
                                 font=ctk.CTkFont(size=8),
                                 text_color="white").pack(side="left", padx=(8,2))
                    def _rem(k=key, o=opt):
                        _mf[k][o] = False
                        _rebuild_tags_bar(); _rebuild()
                    ctk.CTkButton(tag_f, text="×", width=16, height=16,
                                  fg_color="transparent", text_color="white",
                                  font=ctk.CTkFont(size=9),
                                  command=_rem).pack(side="left", padx=(0,4))
            if has_any:
                ctk.CTkButton(tags_bar, text="✕ Limpar filtros", height=20,
                              fg_color="transparent",
                              text_color=("gray40","gray60"),
                              font=ctk.CTkFont(size=9),
                              command=lambda: (
                                  [_mf[k].clear() for k in _mf],
                                  _rebuild_tags_bar(),
                                  _rebuild())
                              ).pack(side="left", padx=8)

        def _abrir_dropdown_multi(key, opcoes, btn_ref):
            """Abre popup de checkboxes para um filtro multi-select."""
            jdd = ctk.CTkToplevel(jp)
            jdd.overrideredirect(True)
            jdd.attributes("-topmost", True)
            jdd.transient(jp)
            # Posiciona abaixo do botão
            jp.update_idletasks()
            bx = btn_ref.winfo_rootx()
            by = btn_ref.winfo_rooty() + btn_ref.winfo_height() + 2
            max_h = min(300, len(opcoes) * 32 + 60)
            jdd.geometry(f"220x{max_h}+{bx}+{by}")
            # Frame com borda
            outer = ctk.CTkFrame(jdd, corner_radius=8,
                                  border_width=1,
                                  border_color=("gray70","gray40"))
            outer.pack(fill="both", expand=True)
            # Header
            hh = ctk.CTkFrame(outer, fg_color=("gray85","gray25"), corner_radius=0)
            hh.pack(fill="x")
            ctk.CTkLabel(hh, text=key.title(),
                         font=ctk.CTkFont(size=10, weight="bold")
                         ).pack(side="left", padx=8, pady=4)
            ctk.CTkButton(hh, text="×", width=22, height=22,
                          fg_color="transparent",
                          command=jdd.destroy).pack(side="right", padx=4)
            # Checkboxes
            sf_dd = ctk.CTkScrollableFrame(outer, fg_color="transparent")
            sf_dd.pack(fill="both", expand=True, padx=4)
            vars_dd = {}
            def _toggle(opt, v=None):
                _mf[key][opt] = bool(vars_dd[opt].get())
                _rebuild_tags_bar()
                _rebuild()
            for opt in opcoes:
                v = ctk.IntVar(value=1 if _mf[key].get(opt) else 0)
                vars_dd[opt] = v
                ctk.CTkCheckBox(sf_dd, text=opt[:30], variable=v,
                                font=ctk.CTkFont(size=10),
                                command=lambda o=opt: _toggle(o)
                                ).pack(anchor="w", pady=2, padx=4)
            # Fechar ao clicar fora
            def _close_outside(e):
                try:
                    if not (jdd.winfo_x() <= e.x_root <= jdd.winfo_x()+jdd.winfo_width() and
                            jdd.winfo_y() <= e.y_root <= jdd.winfo_y()+jdd.winfo_height()):
                        jdd.destroy()
                except: pass
            jdd.bind_all("<Button-1>", _close_outside, add="+")

        # ── Botões de filtro ─────────────────────────────────────────────────
        FILTROS_DEF = [
            ("disciplina",  "Disciplina",   [d for d in discs if d != "Todas"]),
            ("status",      "Status",        [s for s in statuses if s != "Todos"]),
            ("criticidade", "Criticidade",   [c for c in crits if c != "Todas"]),
            ("tipo",        "Tipo",          [t for t in tipos_f if t != "Todos"]),
            ("etapa",       "Etapa",         [e for e in etapas_f if e != "Todas"]),
            ("local",       "Local",         [l for l in locais_f if l != "Todos"]),
        ]
        _btn_refs = {}
        for key, label, opts in FILTROS_DEF:
            btn_f = ctk.CTkButton(ff, text=f"{label} ▾", height=26, width=90,
                                   fg_color=("gray78","gray30"),
                                   hover_color=("gray68","gray25"),
                                   text_color=("gray10","gray90"),
                                   font=ctk.CTkFont(size=9))
            btn_f.configure(command=lambda k=key, o=opts, b=btn_f:
                            _abrir_dropdown_multi(k, o, b))
            btn_f.pack(side="left", padx=2)
            _btn_refs[key] = btn_f

        # ── Filtro de Período ─────────────────────────────────────────────────
        ctk.CTkLabel(ff, text="Período:", font=ctk.CTkFont(size=9),
                     text_color="gray").pack(side="left", padx=(6,0))
        _periodo = {"de": None, "ate": None}   # datetime objects
        lbl_periodo = ctk.CTkLabel(ff, text="Todas as datas",
                                    width=130, height=24,
                                    font=ctk.CTkFont(size=9),
                                    fg_color=("gray80","gray30"),
                                    corner_radius=4,
                                    cursor="hand2")
        lbl_periodo.pack(side="left", padx=(2,2))
        ctk.CTkButton(ff, text="✕", width=22, height=22,
                      fg_color=("gray70","gray35"),
                      font=ctk.CTkFont(size=10),
                      command=lambda: (_periodo.update({"de":None,"ate":None}),
                                       lbl_periodo.configure(text="Todas as datas"),
                                       _rebuild())
                      ).pack(side="left", padx=(0,4))

        def _abrir_range_calendar():
            """Abre calendário de intervalo estilo passagem aérea."""
            import calendar as _cal
            from datetime import datetime as _dtr, timedelta as _td

            jcal = ctk.CTkToplevel(jp)
            jcal.title("Selecionar Período")
            self._centrar_janela(jcal, 560, 360)
            jcal.attributes("-topmost", True)
            jcal.transient(jp)
            jcal.resizable(False, False)
            jcal.lift()
            jcal.focus_force()

            hoje   = _dtr.now()
            _nav   = {"ano": hoje.year, "mes": hoje.month}   # mês visível esquerdo
            _sel   = {"de": _periodo["de"], "ate": _periodo["ate"]}
            _hover = {"data": None}

            # ── Cores ─────────────────────────────────────────────────────────
            COR_NORMAL   = ("gray92", "gray20")
            COR_HOVER    = ("#AED6F1", "#1A5276")
            COR_SEL      = ("#2980B9", "#1A5276")
            COR_RANGE    = ("#D6EAF8", "#0E3A5C")
            COR_HOJE     = ("#27AE60", "#1E8449")
            COR_DESAB    = ("gray80", "gray35")
            TXT_SEL      = "white"
            TXT_NORMAL   = ("gray10", "gray90")
            TXT_DESAB    = "gray"

            # ── Header ────────────────────────────────────────────────────────
            top_bar = ctk.CTkFrame(jcal, fg_color=("#1A5276","#0E2F44"), height=44)
            top_bar.pack(fill="x"); top_bar.pack_propagate(False)
            ctk.CTkLabel(top_bar, text="Selecione o período da análise",
                         font=ctk.CTkFont(size=12, weight="bold"),
                         text_color="white").pack(side="left", padx=16, pady=8)
            lbl_sel_info = ctk.CTkLabel(top_bar, text="",
                                         font=ctk.CTkFont(size=10),
                                         text_color="#AED6F1")
            lbl_sel_info.pack(side="right", padx=16)

            # ── Dois meses lado a lado ─────────────────────────────────────────
            cal_area = ctk.CTkFrame(jcal, fg_color="transparent")
            cal_area.pack(fill="both", expand=True, padx=12, pady=8)
            cal_area.grid_columnconfigure(0, weight=1)
            cal_area.grid_columnconfigure(1, weight=1)

            btn_grid = {}   # {(mes_offset, row, col): CTkButton}
            day_map  = {}   # {(mes_offset, row, col): date_obj}

            DIAS_SEMANA = ["Seg","Ter","Qua","Qui","Sex","Sáb","Dom"]
            MESES_PT    = ["","Jan","Fev","Mar","Abr","Mai","Jun",
                           "Jul","Ago","Set","Out","Nov","Dez"]

            def _get_mes(offset):
                m = _nav["mes"] + offset
                a = _nav["ano"]
                while m > 12: m -= 12; a += 1
                while m < 1:  m += 12; a -= 1
                return a, m

            def _cor_dia(d):
                """Retorna (fg_color, text_color) para o dia d (datetime)."""
                de  = _sel["de"]
                ate = _sel["ate"] or _hover["data"]
                if de and ate and ate < de: ate = None
                is_de  = de  and d == de
                is_ate = ate and d == ate and _sel["ate"]
                in_range = (de and ate and de < d < ate)
                is_hoje  = (d.year==hoje.year and d.month==hoje.month and d.day==hoje.day)
                if is_de or is_ate: return COR_SEL, TXT_SEL
                if in_range:        return COR_RANGE, TXT_NORMAL
                if is_hoje:         return COR_HOJE, TXT_SEL
                return COR_NORMAL, TXT_NORMAL

            def _draw_calendars():
                for w in cal_area.winfo_children(): w.destroy()
                btn_grid.clear(); day_map.clear()
                for offset in (0, 1):
                    ano, mes = _get_mes(offset)
                    col_root = ctk.CTkFrame(cal_area, fg_color=("gray92","gray17"),
                                             corner_radius=8)
                    col_root.grid(row=0, column=offset, padx=4, sticky="nsew", ipadx=4, ipady=4)
                    # Mês + navegação
                    nav_row = ctk.CTkFrame(col_root, fg_color="transparent")
                    nav_row.pack(fill="x", pady=(4,2))
                    if offset == 0:
                        ctk.CTkButton(nav_row, text="◀", width=28, height=26,
                                      fg_color="transparent",
                                      command=lambda: _nav_mes(-1)).pack(side="left", padx=2)
                    ctk.CTkLabel(nav_row,
                                 text=f"{MESES_PT[mes]} {ano}",
                                 font=ctk.CTkFont(size=11, weight="bold")
                                 ).pack(side="left", expand=True)
                    if offset == 1:
                        ctk.CTkButton(nav_row, text="▶", width=28, height=26,
                                      fg_color="transparent",
                                      command=lambda: _nav_mes(1)).pack(side="right", padx=2)
                    # Dias da semana
                    sem_row = ctk.CTkFrame(col_root, fg_color="transparent")
                    sem_row.pack(fill="x")
                    for ds in DIAS_SEMANA:
                        ctk.CTkLabel(sem_row, text=ds, width=34,
                                     font=ctk.CTkFont(size=8),
                                     text_color="gray").pack(side="left")
                    # Grid de dias
                    grid_f = ctk.CTkFrame(col_root, fg_color="transparent")
                    grid_f.pack(fill="x")
                    weeks = _cal.monthcalendar(ano, mes)
                    for rr, week in enumerate(weeks):
                        for cc, dia in enumerate(week):
                            if dia == 0:
                                ctk.CTkFrame(grid_f, width=34, height=30,
                                              fg_color="transparent"
                                              ).grid(row=rr, column=cc, padx=1, pady=1)
                                continue
                            d_obj = _dtr(ano, mes, dia)
                            fc, tc = _cor_dia(d_obj)
                            b = ctk.CTkButton(
                                grid_f, text=str(dia),
                                width=34, height=30, corner_radius=6,
                                fg_color=fc, text_color=tc,
                                hover_color=COR_HOVER,
                                font=ctk.CTkFont(size=10),
                                command=lambda d=d_obj: _click_dia(d))
                            b.grid(row=rr, column=cc, padx=1, pady=1)
                            b.bind("<Enter>", lambda e, d=d_obj: _on_hover(d))
                            b.bind("<Leave>", lambda e: _on_hover(None))
                            btn_grid[(offset, rr, cc)] = b
                            day_map[(offset, rr, cc)]  = d_obj

            def _update_info():
                de  = _sel["de"]
                ate = _sel["ate"]
                if de and ate:
                    delta = (ate - de).days
                    lbl_sel_info.configure(
                        text=f"{de.strftime('%d/%m/%Y')} → {ate.strftime('%d/%m/%Y')}  ({delta} dias)")
                elif de:
                    lbl_sel_info.configure(text=f"De: {de.strftime('%d/%m/%Y')} — clique para data final")
                else:
                    lbl_sel_info.configure(text="")

            def _on_hover(d):
                _hover["data"] = d
                if _sel["de"] and not _sel["ate"]:
                    _refresh_colors()

            def _refresh_colors():
                """Atualiza apenas as cores sem redesenhar tudo."""
                for key2, btn2 in btn_grid.items():
                    d_obj = day_map.get(key2)
                    if not d_obj: continue
                    fc, tc = _cor_dia(d_obj)
                    try: btn2.configure(fg_color=fc, text_color=tc)
                    except: pass

            def _click_dia(d):
                if _sel["de"] is None or (_sel["de"] and _sel["ate"]):
                    # Primeira seleção (ou reinício)
                    _sel["de"]  = d
                    _sel["ate"] = None
                    _hover["data"] = None
                else:
                    # Segunda seleção
                    if d < _sel["de"]:   # clicou antes — inverte
                        _sel["ate"] = _sel["de"]
                        _sel["de"]  = d
                    else:
                        _sel["ate"] = d
                _refresh_colors()
                _update_info()

            def _nav_mes(delta):
                _nav["mes"] += delta
                if _nav["mes"] > 12: _nav["mes"] = 1;  _nav["ano"] += 1
                if _nav["mes"] < 1:  _nav["mes"] = 12; _nav["ano"] -= 1
                _draw_calendars()

            def _aplicar():
                if not _sel["de"]:
                    return  # nada selecionado
                _periodo["de"]  = _sel["de"]
                _periodo["ate"] = _sel["ate"] or _sel["de"]
                de_s  = _periodo["de"].strftime("%d/%m/%Y")
                ate_s = _periodo["ate"].strftime("%d/%m/%Y")
                if de_s == ate_s:
                    lbl_periodo.configure(text=de_s)
                else:
                    lbl_periodo.configure(text=f"{de_s} → {ate_s}")
                jcal.destroy()
                _rebuild()

            # Botões de ação
            act_row = ctk.CTkFrame(jcal, fg_color="transparent")
            act_row.pack(fill="x", padx=16, pady=(0,10))
            ctk.CTkButton(act_row, text="Limpar", width=80, height=30,
                          fg_color=("gray75","gray35"),
                          command=lambda: (_sel.update({"de":None,"ate":None}),
                                           _hover.update({"data":None}),
                                           _draw_calendars(),
                                           _update_info())
                          ).pack(side="left")
            ctk.CTkButton(act_row, text="✅ Aplicar período", height=30,
                          fg_color="#27AE60", hover_color="#1E8449",
                          font=ctk.CTkFont(size=11, weight="bold"),
                          command=_aplicar).pack(side="right")

            _draw_calendars()
            _update_info()

        lbl_periodo.bind("<Button-1>", lambda e: _abrir_range_calendar())

        # ── ÁREA DE CONTEÚDO DINÂMICO ─────────────────────────────────────────
        content_frame = ctk.CTkFrame(scroll_root, fg_color="transparent")
        content_frame.pack(fill="both", expand=True, padx=12)

        def _rebuild():
            for w in content_frame.winfo_children(): w.destroy()
            issues = _issues_filtrados()
            if not self.lista_issues:
                ctk.CTkLabel(content_frame,
                             text="Nenhum apontamento criado ainda.\n\n"
                                  "Crie apontamentos na prancha e volte aqui.",
                             text_color="gray",
                             font=ctk.CTkFont(size=13),
                             justify="center").pack(expand=True, pady=60)
                return
            atrasados = [i for i in issues if _is_atrasado(i)]
            resolvidos = [i for i in issues if i.get('status') == 'Resolvido']
            em_aberto  = [i for i in issues if i.get('status') == 'Em aberto']
            total = len(issues)

            # ── KPI CARDS ────────────────────────────────────────────────────
            kpi_row = ctk.CTkFrame(content_frame, fg_color="transparent")
            kpi_row.pack(fill="x", pady=(4,8))
            for col in range(4): kpi_row.grid_columnconfigure(col, weight=1)

            def _kpi(parent, col, value, label, bg, icon):
                card = ctk.CTkFrame(parent, corner_radius=10, fg_color=bg)
                card.grid(row=0, column=col, padx=4, sticky="ew", ipady=8)
                ctk.CTkLabel(card, text=icon,
                             font=ctk.CTkFont(size=22)).pack(pady=(8,2))
                ctk.CTkLabel(card, text=str(value),
                             font=ctk.CTkFont(size=28, weight="bold"),
                             text_color="white").pack()
                ctk.CTkLabel(card, text=label,
                             font=ctk.CTkFont(size=9),
                             text_color="white").pack(pady=(0,8))

            _kpi(kpi_row, 0, total,          "Total",       "#2980B9", "📋")
            _kpi(kpi_row, 1, len(em_aberto), "Em Aberto",   "#E67E22", "🔓")
            _kpi(kpi_row, 2, len(resolvidos),"Resolvidos",  "#27AE60", "✅")
            _kpi(kpi_row, 3, len(atrasados), "Atrasados",   "#E74C3C", "⏰")

            # ── GRÁFICOS ──────────────────────────────────────────────────────
            charts_row = ctk.CTkFrame(content_frame, fg_color="transparent")
            charts_row.pack(fill="x", pady=(0,8))
            charts_row.grid_columnconfigure(0, weight=1)
            charts_row.grid_columnconfigure(1, weight=2)

            # ── Gráfico rosca (status) ────────────────────────────────────────
            donut_frame = ctk.CTkFrame(charts_row, corner_radius=10,
                                       fg_color=("gray92","gray16"))
            donut_frame.grid(row=0, column=0, padx=(0,6), sticky="nsew", ipady=8)
            ctk.CTkLabel(donut_frame, text="Status dos Apontamentos",
                         font=ctk.CTkFont(size=10, weight="bold")).pack(pady=(8,2))

            donut_canvas = tk.Canvas(donut_frame, width=170, height=150,
                                      bg=donut_frame.cget("fg_color") if isinstance(donut_frame.cget("fg_color"), str) else "#EBEBEB",
                                      highlightthickness=0)
            donut_canvas.pack(pady=4)

            def _draw_donut():
                donut_canvas.delete("all")
                bg_col = "#EBEBEB" if ctk.get_appearance_mode() == "Light" else "#222222"
                donut_canvas.configure(bg=bg_col)
                cx_d, cy_d, R, r = 85, 75, 58, 32
                data = [
                    (len(em_aberto),  "#E67E22", "Em aberto"),
                    (len(resolvidos), "#27AE60", "Resolvidos"),
                    (len(atrasados),  "#E74C3C", "Atrasados"),
                    (max(0, total - len(em_aberto) - len(resolvidos) - len(atrasados)),
                     "#8E44AD", "Outros"),
                ]
                data = [(v, c, l) for v, c, l in data if v > 0]
                total_d = sum(v for v, _, _ in data) or 1
                start = -90.0
                for val, color, lbl in data:
                    extent = 360.0 * val / total_d
                    donut_canvas.create_arc(
                        cx_d-R, cy_d-R, cx_d+R, cy_d+R,
                        start=start, extent=extent,
                        fill=color, outline="white", width=2, style="pieslice")
                    start += extent
                # Buraco central
                donut_canvas.create_oval(cx_d-r, cy_d-r, cx_d+r, cy_d+r,
                                          fill=bg_col, outline=bg_col)
                # Número central
                donut_canvas.create_text(cx_d, cy_d, text=str(total),
                                          font=("Arial", 16, "bold"),
                                          fill="#2C3E50" if ctk.get_appearance_mode()=="Light" else "white")
                donut_canvas.create_text(cx_d, cy_d+16, text="total",
                                          font=("Arial", 8), fill="gray")
                # Legenda
                ly = 140
                lx = 6
                for val, color, lbl in data:
                    donut_canvas.create_rectangle(lx, ly, lx+10, ly+8, fill=color, outline="")
                    donut_canvas.create_text(lx+14, ly+4, anchor="w",
                                              text=f"{lbl} ({val})",
                                              font=("Arial", 7),
                                              fill="#2C3E50" if ctk.get_appearance_mode()=="Light" else "#CCCCCC")
                    lx += 58
            _draw_donut()

            # ── Barras horizontais por disciplina ────────────────────────────
            bars_frame = ctk.CTkFrame(charts_row, corner_radius=10,
                                       fg_color=("gray92","gray16"))
            bars_frame.grid(row=0, column=1, padx=(6,0), sticky="nsew", ipady=8)
            ctk.CTkLabel(bars_frame, text="Apontamentos por Disciplina",
                         font=ctk.CTkFont(size=10, weight="bold")).pack(pady=(8,4), anchor="w", padx=12)

            disc_count = {}
            disc_atr   = {}
            for iss in issues:
                d2 = iss.get('disciplina','?')
                disc_count[d2] = disc_count.get(d2, 0) + 1
                if _is_atrasado(iss): disc_atr[d2] = disc_atr.get(d2, 0) + 1
            sorted_discs = sorted(disc_count.items(), key=lambda x: x[1], reverse=True)[:8]
            max_v = max((v for _, v in sorted_discs), default=1)

            DISC_COLORS = {
                "Arquitetura": "#3498DB", "Estrutura": "#E74C3C",
                "Elétrica": "#F39C12",   "Hidráulica": "#1ABC9C",
                "HVAC": "#9B59B6",       "Incêndio": "#E67E22",
                "Coordenação": "#2C3E50","Topografia": "#27AE60",
            }
            for disc_n, count_n in sorted_discs:
                row_b = ctk.CTkFrame(bars_frame, fg_color="transparent")
                row_b.pack(fill="x", padx=12, pady=2)
                # Label disc
                ctk.CTkLabel(row_b, text=disc_n[:14], width=90, anchor="w",
                             font=ctk.CTkFont(size=9)).pack(side="left")
                # Barra
                bar_bg = ctk.CTkFrame(row_b, height=16, corner_radius=4,
                                       fg_color=("gray80","gray30"))
                bar_bg.pack(side="left", fill="x", expand=True, padx=(0,6))
                pct = count_n / max_v
                bar_fill = ctk.CTkFrame(bar_bg, height=16, corner_radius=4,
                                         fg_color=DISC_COLORS.get(disc_n, "#2980B9"),
                                         width=max(12, int(pct * 280)))
                bar_fill.place(relx=0, rely=0, relheight=1,
                               relwidth=pct)
                # Valor
                atr_txt = f"  ⏰{disc_atr[disc_n]}" if disc_n in disc_atr else ""
                ctk.CTkLabel(row_b,
                             text=f"{count_n}{atr_txt}",
                             width=46, font=ctk.CTkFont(size=9),
                             text_color="#E74C3C" if disc_n in disc_atr else ("gray20","gray80")
                             ).pack(side="left")

            # ── ATRASADOS ─────────────────────────────────────────────────────
            if atrasados:
                atr_frame = ctk.CTkFrame(content_frame, corner_radius=10,
                                          fg_color=("#FADBD8","#4A1010"),
                                          border_width=1,
                                          border_color=("#E74C3C","#922B21"))
                atr_frame.pack(fill="x", pady=(0,8))
                ctk.CTkLabel(atr_frame,
                             text=f"⏰  Apontamentos Atrasados  ({len(atrasados)})",
                             font=ctk.CTkFont(size=11, weight="bold"),
                             text_color=("#922B21","#E74C3C")).pack(anchor="w", padx=12, pady=(8,4))
                for iss in sorted(atrasados, key=_dias_atraso, reverse=True)[:8]:
                    dias = _dias_atraso(iss)
                    arow = ctk.CTkFrame(atr_frame, corner_radius=6,
                                         fg_color=("white","#3A0A0A"))
                    arow.pack(fill="x", padx=8, pady=2)
                    ctk.CTkLabel(arow,
                                 text=iss['id'],
                                 width=58, font=ctk.CTkFont(size=10, weight="bold"),
                                 text_color="#E74C3C").pack(side="left", padx=(8,4))
                    ctk.CTkLabel(arow,
                                 text=iss.get('titulo','')[:55],
                                 anchor="w", font=ctk.CTkFont(size=10)
                                 ).pack(side="left", fill="x", expand=True)
                    ctk.CTkLabel(arow,
                                 text=f"+{dias}d",
                                 width=40, font=ctk.CTkFont(size=10, weight="bold"),
                                 text_color="#E74C3C").pack(side="right", padx=8, pady=4)

            # ── TABELA DE APONTAMENTOS ─────────────────────────────────────────
            tbl_hdr = ctk.CTkFrame(content_frame, fg_color=("gray88","gray20"), corner_radius=8)
            tbl_hdr.pack(fill="x", pady=(0,2))
            ctk.CTkLabel(tbl_hdr,
                         text=f"📋  Lista de Apontamentos  ({total})",
                         font=ctk.CTkFont(size=11, weight="bold")).pack(side="left", padx=12, pady=6)

            tbl = ctk.CTkScrollableFrame(content_frame, fg_color="transparent", height=220)
            tbl.pack(fill="x", pady=(0,12))

            # Cabeçalho da tabela
            cols = [("ID",55),("Título",200),("Disciplina",90),
                    ("Status",80),("Criticidade",120),("Prazo",80),("Local",90)]
            head_row = ctk.CTkFrame(tbl, fg_color=("#2980B9","#1A5276"), corner_radius=4)
            head_row.pack(fill="x", pady=(0,2))
            for col_lbl, col_w in cols:
                ctk.CTkLabel(head_row, text=col_lbl, width=col_w,
                             font=ctk.CTkFont(size=9, weight="bold"),
                             text_color="white").pack(side="left", padx=2, pady=4)

            # Linhas
            COR_STATUS = {"Resolvido":("#D5F5E3","#1A4A2A"),
                          "Em aberto":("gray92","gray16"),
                          "Reprovados":("#FADBD8","#4A1010")}
            # Ordena por proximidade do prazo:
            # 1. Atrasados (prazo já passou) → mais atrasados primeiro
            # 2. Com prazo futuro → mais próximo de vencer primeiro
            # 3. Sem prazo → por último
            def _sort_key(iss_):
                prazos = [p.get('prazo','') for p in iss_.get('participantes',{}).values()
                          if p.get('prazo','').strip() and not p.get('conclusao','').strip()]
                if not prazos: return (2, 9999)   # sem prazo: último
                try:
                    from datetime import datetime as _dt2
                    hoje = _dt2.now().replace(hour=0,minute=0,second=0,microsecond=0)
                    datas = [_dt2.strptime(p, "%d/%m/%Y") for p in prazos]
                    diff  = min((d - hoje).days for d in datas)
                    if diff < 0:  return (0, diff)   # atrasado: menor diff primeiro
                    else:         return (1, diff)   # futuro: menor diff primeiro
                except: return (2, 9999)
            issues_sorted = sorted(issues, key=_sort_key)
            for idx_r, iss in enumerate(issues_sorted):
                bg = COR_STATUS.get(iss.get('status',''), ("gray92","gray16"))
                if _is_atrasado(iss): bg = ("#FADBD8","#4A1010")
                trow = ctk.CTkFrame(tbl, fg_color=bg, corner_radius=4)
                trow.pack(fill="x", pady=1)

                def _fmt_prazo(iss_=iss):
                    prazos = [p.get('prazo','') for p in iss_.get('participantes',{}).values() if p.get('prazo')]
                    return min(prazos) if prazos else "—"

                loc_raw = iss.get('local','')
                loc_str = self._fmt_local(loc_raw) if loc_raw else "—"
                prio_str = self.strip_emoji_prio(iss.get('prioridade',''))

                for val, col_w in [
                    (iss['id'], 55),
                    (iss.get('titulo','')[:28], 200),
                    (iss.get('disciplina','')[:12], 90),
                    (iss.get('status',''), 80),
                    (prio_str[:18], 120),
                    (_fmt_prazo(), 80),
                    (loc_str[:12], 90),
                ]:
                    ctk.CTkLabel(trow, text=val, width=col_w,
                                 font=ctk.CTkFont(size=9),
                                 anchor="w").pack(side="left", padx=2, pady=3)

                # Clique abre editor
                def _abrir(i=iss, r=trow):
                    r.configure(fg_color=("#AED6F1","#1A3A5C"))
                    self.abrir_janela_issue(i)
                trow.bind("<Button-1>", lambda e, fn=_abrir: fn())
                for child in trow.winfo_children():
                    child.bind("<Button-1>", lambda e, fn=_abrir: fn())
                trow.configure(cursor="hand2")

        # Aguarda window render antes de popular conteúdo
        def _safe_rebuild():
            try:
                _rebuild()
            except Exception as _e:
                import traceback as _tb
                print("Painel BI erro:", _tb.format_exc())
        jp.after(150, _safe_rebuild)


    def abrir_menu_filtros(self):
        j = ctk.CTkToplevel(self); j.title("Filtros"); j.geometry("420x640")
        j.attributes("-topmost", True); j.grab_set()
        fr = ctk.CTkScrollableFrame(j); fr.pack(fill="both", expand=True, padx=10, pady=10)

        # ── Texto ─────────────────────────────────────────────────────────────
        ctk.CTkLabel(fr, text="Texto / Busca:",
                     font=ctk.CTkFont(weight="bold")).pack(anchor="w")
        et = ctk.CTkEntry(fr, placeholder_text="Pesquisar em título e descrição…")
        et.insert(0, self.filtros_ativos['texto'])
        et.pack(fill="x", pady=(2, 12))

        # ── Helper: seção multi-select com checkboxes ─────────────────────────
        sel_vars = {}   # {field: {opção: BoolVar}}

        def _secao(label, field, opcoes):
            ctk.CTkLabel(fr, text=label,
                         font=ctk.CTkFont(weight="bold")).pack(anchor="w", pady=(4, 2))
            box = ctk.CTkFrame(fr, fg_color=("gray88", "gray18"), corner_radius=8)
            box.pack(fill="x", padx=2, pady=(0, 10), ipadx=6, ipady=4)
            sel_vars[field] = {}
            cur = self.filtros_ativos.get(field, set())
            # Mini-links "✓ Todos" / "✗ Limpar"
            ctrl = ctk.CTkFrame(box, fg_color="transparent"); ctrl.pack(fill="x", padx=6)
            def _sa(f=field):
                for v in sel_vars[f].values(): v.set(True)
            def _ca(f=field):
                for v in sel_vars[f].values(): v.set(False)
            ctk.CTkButton(ctrl, text="✓ Todos", width=64, height=20,
                          fg_color="transparent", text_color=("gray40","gray65"),
                          font=ctk.CTkFont(size=10), hover_color=("gray80","gray30"),
                          command=_sa).pack(side="left")
            ctk.CTkButton(ctrl, text="✗ Limpar", width=64, height=20,
                          fg_color="transparent", text_color=("gray40","gray65"),
                          font=ctk.CTkFont(size=10), hover_color=("gray80","gray30"),
                          command=_ca).pack(side="left")
            # Checkboxes
            for opt in opcoes:
                var = ctk.BooleanVar(value=(opt in cur))
                sel_vars[field][opt] = var
                ctk.CTkCheckBox(box, text=opt, variable=var,
                                font=ctk.CTkFont(size=12)).pack(anchor="w", padx=8, pady=1)

        _secao("Status:", "status",
               ["Em aberto", "Resolvido", "Reprovado", "Em análise", "Atrasados"])
        _secao("Disciplina:", "disciplina", list(self.opcoes_disciplina))
        _secao("Criticidade:", "criticidade",
               ["Severa / Imediata", "Importante / Programada", "Observação / Atenção"])
        _secao("Tipo:", "tipo", list(self.tipos_apontamento))

        # ── Botões ────────────────────────────────────────────────────────────
        def _aplicar():
            for field, vars_map in sel_vars.items():
                self.filtros_ativos[field] = {opt for opt, v in vars_map.items() if v.get()}
            self.filtros_ativos['texto'] = et.get().strip().lower()
            self.atualizar_painel_issues(); j.destroy()

        def _limpar():
            self.filtros_ativos.update({
                'texto': '', 'status': set(), 'disciplina': set(),
                'criticidade': set(), 'tipo': set(),
                'data_criacao_inicio': '', 'data_criacao_fim': ''})
            self.atualizar_painel_issues(); j.destroy()

        j.bind("<Return>", lambda e: _aplicar())
        bf = ctk.CTkFrame(j, fg_color="transparent"); bf.pack(fill="x", padx=10, pady=10)
        ctk.CTkButton(bf, text="Limpar tudo", width=100, fg_color="gray",
                      command=_limpar).pack(side="left")
        ctk.CTkButton(bf, text="Cancelar", width=80, fg_color="transparent",
                      text_color=("gray30","gray70"), hover_color=("gray85","gray25"),
                      command=j.destroy).pack(side="right", padx=6)
        ctk.CTkButton(bf, text="Aplicar", width=100,
                      fg_color=COR.get('info','#2980B9'),
                      command=_aplicar).pack(side="right")

    # ── ADICIONAR PRANCHA (sidebar) ───────────────────────────────────────────

    def _adicionar_prancha_sidebar(self):
        if len(self.camadas_ids) >= 4:
            messagebox.showwarning("Limite","Máximo de 4 pranchas.",parent=self)
            return
        jp = ctk.CTkToplevel(self); jp.title("Adicionar Prancha")
        self._centrar_janela(jp, 440, 230); jp.attributes("-topmost",True); jp.grab_set()
        ctk.CTkLabel(jp, text="Adicionar Prancha",
                     font=ctk.CTkFont(size=16,weight="bold")).pack(pady=(15,5))
        rf = ctk.CTkFrame(jp, fg_color="transparent"); rf.pack(fill="x",padx=20,pady=5)
        ctk.CTkLabel(rf, text="Disciplina:", width=80, anchor="w").pack(side="left")
        cd = ctk.CTkComboBox(rf, values=self.opcoes_disciplina, width=150)
        cd.pack(side="left", padx=5)
        lbl = ctk.CTkLabel(jp, text="Nenhum arquivo", text_color="gray")
        lbl.pack(pady=2)
        cam = {'v': None}
        def sel():
            p = filedialog.askopenfilename(
                filetypes=[("PDF/DXF","*.pdf *.dxf")],parent=jp)
            if p:
                cam['v'] = p
                lbl.configure(text=os.path.basename(p), text_color="#2ecc71")
        ctk.CTkButton(jp, text="📎 Selecionar PDF/DXF", command=sel).pack(pady=5)
        def confirmar():
            if not cam['v']:
                messagebox.showwarning("Aviso","Selecione um arquivo.",parent=jp)
                return
            new_c = f"camada_{len(self.camadas_ids)}"
            disc  = cd.get()
            if disc in self.mapa_arquivos: disc = f"{disc}_{len(self.camadas_ids)}"
            self.camadas_ids.append(new_c)
            self.ordem_renderizacao.append(new_c)
            self.nomes_arquivos[new_c]   = disc
            self.mapa_arquivos[disc]     = new_c
            self.caminhos_arquivos[new_c]= cam['v']
            self.camadas_pdf[new_c] = {
                'path': cam['v'], 'pil_original': None,
                'opacity': 0.8, 'color_mode': 'Original',  # 20% transparência padrão
                'visible': True, 'disc_name': disc,
                'display': {'line_color':None,'line_thickness':1.0,
                            'remove_hatch':False,'bg_color':None,
                            'contrast':1.0,'preset':'Original'},
            }
            self.menu_arquivo_alvo.configure(values=list(self.mapa_arquivos.keys()))
            jp.destroy()
            self._rebuild_prancha_list()
            self.marcar_alterado()
            if cam['v'].lower().endswith('.pdf'):
                self._carregar_pdf_async(new_c)
            else:
                self._carregar_dxf_como_pdf(new_c)
        ctk.CTkButton(jp, text="✅ Adicionar",
                      fg_color="#27AE60", hover_color="#1E8449",
                      command=confirmar).pack(pady=8)

    # ── SALVAR / ABRIR ────────────────────────────────────────────────────────

    def salvar_analise(self):
        caminho = filedialog.asksaveasfilename(
            defaultextension=".auria",
            filetypes=[("Arquivo Auria","*.auria"),
                       ("Arquivo legado","*.proj")],
            title="Salvar Análise")
        if not caminho: return False
        dados = {
            'meta': {
                'empreendimento': self.meta_empreendimento,
                'analista':       self.meta_analista,
                'etapa':          self.meta_etapa,
                'tipo_analise':   self.meta_tipo_analise,
                'config_penas':   self.config_penas,
                'versao':         '0.5-pdf',
            },
            'arquivos': {
                'camadas_ids':         self.camadas_ids,
                'ordem_renderizacao':  self.ordem_renderizacao,
                'caminhos_arquivos':   self.caminhos_arquivos,
                'nomes_arquivos':      self.nomes_arquivos,
                'mapa_arquivos':       self.mapa_arquivos,
                'camadas_estado':      {
                    c: {
                        'opacity':    self.camadas_pdf.get(c,{}).get('opacity',1.0),
                        'color_mode': self.camadas_pdf.get(c,{}).get('color_mode','Original'),
                        'visible':    self.camadas_pdf.get(c,{}).get('visible',True),
                        'offset':     list(self._layer_offset.get(c,(0.0,0.0))),
                        'scale':      self._layer_scale.get(c, 1.0),
                        'display':    self.camadas_pdf.get(c,{}).get('display',{}),
                    }
                    for c in self.camadas_ids
                }
            },
            'issues': [],
            'trena': {
                'calibrada':   self._trena_calibrada,
                'px_por_m':    self._trena_px_por_m,
                'cotas': [
                    {'id':c['id'],'nx1':c['nx1'],'ny1':c['ny1'],
                     'nx2':c['nx2'],'ny2':c['ny2'],
                     'metros':c['metros'],'label':c['label'],
                     'visible':c.get('visible',True)}
                    for c in self._cotas
                ],
                'cota_id_counter': self._cota_id_counter,
            }
        }
        for issue in self.lista_issues:
            ic = issue.copy()
            ic['pontos_salvos'] = [
                {'dxf_x': pt.get('dxf_x',0), 'dxf_y': pt.get('dxf_y',0)}
                for pt in issue.get('pontos', [])]
            ic.pop('pontos', None)
            ic['imagens_b64'] = [self.img_to_b64(img)
                                  for img in issue.get('imagens', [])]
            ic.pop('imagens', None)
            ic['drawings'] = issue.get('drawings', [])
            dados['issues'].append(ic)
        try:
            with open(caminho,'w',encoding='utf-8') as f:
                json.dump(dados, f, ensure_ascii=False, indent=2)
            self.unsaved_changes = False
            self._arquivo_aberto = caminho
            self._db_init()   # garante schema no caminho correto
            threading.Thread(daemon=True, target=self._db_sync).start()
            threading.Thread(daemon=True, target=self._supa_sync_apontamentos).start()
            messagebox.showinfo("Sucesso","Análise salva com sucesso!\n(.auria)",parent=self)
            return True
        except Exception as e:
            messagebox.showerror("Erro",f"Erro ao salvar:\n{e}",parent=self)
            return False

    def abrir_analise(self):
        if self.unsaved_changes:
            r = messagebox.askyesnocancel("Atenção",
                "Salvar antes de abrir outra?",parent=self)
            if r is True:
                if not self.salvar_analise(): return
            elif r is None: return
        caminho = filedialog.askopenfilename(
            filetypes=[("Arquivo Auria","*.auria *.proj"),
                       ("Arquivo Auria","*.auria"),
                       ("Arquivo legado","*.proj")],
            title="Abrir Análise")
        if not caminho: return
        try:
            with open(caminho,'r',encoding='utf-8') as f:
                dados = json.load(f)
            for a in ['sidebar_frame','drag_handle','right_frame']:
                if hasattr(self,a):
                    try: getattr(self,a).destroy()
                    except: pass
            for a in ['frame_passo_1','frame_passo_2']:
                if hasattr(self,a) and getattr(self,a).winfo_exists():
                    try: getattr(self,a).destroy()
                    except: pass
            self.reset_sessao()
            m = dados['meta']
            self.meta_empreendimento = m.get('empreendimento','')
            self.meta_analista       = m.get('analista','')
            self.meta_etapa          = m.get('etapa','')
            self.meta_tipo_analise   = m.get('tipo_analise','')
            pc = m.get('config_penas',{})
            self.config_penas = {int(k):v for k,v in pc.items()} if pc else {1:1,2:1,3:3,4:2,5:1,6:2,7:1}
            ad = dados.get('arquivos',{})
            self.camadas_ids         = ad.get('camadas_ids',[])
            self.caminhos_arquivos   = ad.get('caminhos_arquivos',{})
            self.nomes_arquivos      = ad.get('nomes_arquivos',{})
            self.mapa_arquivos       = ad.get('mapa_arquivos',{})
            self.ordem_renderizacao  = ad.get('ordem_renderizacao', self.camadas_ids.copy())
            if self.camadas_ids:
                self.camada_fundo_id  = self.camadas_ids[0]
                self.disciplina_ativa = self.nomes_arquivos.get(self.camadas_ids[0])
            estados = ad.get('camadas_estado',{})
            for c in self.camadas_ids:
                est = estados.get(c,{})
                self.camadas_pdf[c] = {
                    'path':         self.caminhos_arquivos.get(c,''),
                    'pil_original': None,
                    'opacity':      est.get('opacity',1.0),
                    'color_mode':   est.get('color_mode','Original'),
                    'visible':      est.get('visible',True),
                    'disc_name':    self.nomes_arquivos.get(c,''),
                    'n_pages':      1, 'page_num': 0,
                }
                off = est.get('offset', [0.0, 0.0])
                self._layer_offset[c] = (float(off[0]), float(off[1]))
                self._layer_scale[c]  = float(est.get('scale', 1.0))
                # Restaura configurações de exibição
                saved_disp = est.get('display', {})
                if saved_disp:
                    # Converte listas de volta para tuplas (JSON não tem tuple)
                    if saved_disp.get('line_color') and isinstance(
                            saved_disp['line_color'], list):
                        saved_disp['line_color'] = tuple(saved_disp['line_color'])
                    if saved_disp.get('bg_color') and isinstance(
                            saved_disp['bg_color'], list):
                        saved_disp['bg_color'] = tuple(saved_disp['bg_color'])
                    self.camadas_pdf[c]['display'] = saved_disp
            self.montar_interface(); self.update()
            # Carrega issues
            for id_ in dados.get('issues',[]):
                id_['imagens']  = [self.b64_to_img(b64)
                                    for b64 in id_.get('imagens_b64',[])]
                id_.pop('imagens_b64', None)
                id_['pontos']   = [{'dxf_x': pt.get('dxf_x',0),
                                    'dxf_y': pt.get('dxf_y',0)}
                                   for pt in id_.get('pontos_salvos',[])]
                id_.pop('pontos_salvos', None)
                if 'drawings' not in id_: id_['drawings'] = []
                self.lista_issues.append(id_)
                d2  = id_.get('disciplina','GER')
                num = id_.get('id_num',1)
                if d2 in self.contadores_disciplina and num >= self.contadores_disciplina[d2]:
                    self.contadores_disciplina[d2] = num+1
            self.atualizar_painel_issues()
            # ── Restaura trena ─────────────────────────────────────────────
            td = dados.get('trena', {})
            self._trena_calibrada  = td.get('calibrada', False)
            self._trena_px_por_m   = float(td.get('px_por_m', 1.0))
            self._cota_id_counter  = int(td.get('cota_id_counter', 1))
            self._cotas = []
            for cd in td.get('cotas', []):
                self._cotas.append({
                    'id':      int(cd.get('id',0)),
                    'nx1':     float(cd.get('nx1',0)),
                    'ny1':     float(cd.get('ny1',0)),
                    'nx2':     float(cd.get('nx2',0)),
                    'ny2':     float(cd.get('ny2',0)),
                    'metros':  float(cd.get('metros',0)),
                    'label':   cd.get('label',''),
                    'visible': bool(cd.get('visible',True)),
                })
            # Atualiza ribbon da trena (dois botões se calibrada)
            self.after(200, self._rebuild_trena_ribbon)
            self.unsaved_changes = False
            # Carrega imagens
            for c in self.camadas_ids:
                cp = self.caminhos_arquivos.get(c,'')
                if os.path.exists(cp):
                    if cp.lower().endswith('.pdf'):
                        self.after(100, lambda cc=c: self._carregar_pdf_async(cc))
                    elif cp.lower().endswith('.dxf'):
                        self.after(100, lambda cc=c: self._carregar_dxf_como_pdf(cc))
                else:
                    pass  # arquivo não encontrado, user pode recarregar manualmente
            # Redesenha cotas depois que canvas estiver pronto
            self.after(500, self._redesenhar_cotas)
            # Banco de dados — inicializa e sincroniza
            self._arquivo_aberto = caminho
            self._db_init()
            threading.Thread(daemon=True, target=self._db_sync).start()
            threading.Thread(daemon=True, target=self._supa_sync_apontamentos).start()
        except Exception as e:
            messagebox.showerror("Erro",f"Erro ao abrir:\n{e}",parent=self)

    # ── MENUS SECUNDÁRIOS ─────────────────────────────────────────────────────

    def abrir_menu_posicao(self):
        """Menu de Posição, Escala e Alinhamento — redesenhado."""
        if len(self.camadas_ids) < 2:
            messagebox.showinfo("Posição/Escala",
                "Carregue pelo menos 2 pranchas para usar esta função.", parent=self)
            return

        jp = ctk.CTkToplevel(self)
        jp.title("Posição, Escala e Alinhamento")
        self._centrar_janela(jp, 440, 620)
        jp.attributes("-topmost", True)
        jp.resizable(True, True)

        # ── Cabeçalho ─────────────────────────────────────────────────────────
        ctk.CTkLabel(jp, text="⚙️  Posição, Escala e Alinhamento",
                     font=ctk.CTkFont(size=15, weight="bold")).pack(pady=(14,2))

        # ── Trava / Arrastar ──────────────────────────────────────────────────
        fl = ctk.CTkFrame(jp, corner_radius=8, fg_color=("gray88","gray18"))
        fl.pack(fill="x", padx=14, pady=(4,2), ipadx=8, ipady=4)
        fl_row = ctk.CTkFrame(fl, fg_color="transparent"); fl_row.pack(fill="x")

        def tog_bloq():
            self.prancha_bloqueada = sw_bloq.get() == 1
            sw_arr.configure(state="disabled" if self.prancha_bloqueada else "normal")
            if self.prancha_bloqueada:
                self.modo_arrastar = False; sw_arr.deselect()
                self.desenho_canvas.configure(cursor="arrow")
        def tog_arr():
            if self.prancha_bloqueada: sw_arr.deselect(); return
            self.modo_arrastar = sw_arr.get() == 1
            self.desenho_canvas.configure(cursor="fleur" if self.modo_arrastar else "arrow")

        sw_bloq = ctk.CTkSwitch(fl_row, text="🔒 Travar pranchas",
                                 fg_color="gray", progress_color="#E74C3C",
                                 width=44, command=tog_bloq)
        if self.prancha_bloqueada: sw_bloq.select()
        sw_bloq.pack(side="left", padx=6, pady=4)
        sw_arr  = ctk.CTkSwitch(fl_row, text="✋ Arrastar com mouse",
                                 command=tog_arr,
                                 state="disabled" if self.prancha_bloqueada else "normal",
                                 width=44)
        if self.modo_arrastar: sw_arr.select()
        sw_arr.pack(side="left", padx=6, pady=4)
        tog_bloq()

        # ── Seleciona prancha ─────────────────────────────────────────────────
        fps = ctk.CTkFrame(jp, corner_radius=8, fg_color=("gray88","gray18"))
        fps.pack(fill="x", padx=14, pady=2, ipadx=8, ipady=4)
        row_sel = ctk.CTkFrame(fps, fg_color="transparent"); row_sel.pack(fill="x")
        ctk.CTkLabel(row_sel, text="Prancha a mover:",
                     font=ctk.CTkFont(weight="bold", size=11)).pack(side="left", padx=4)
        opcoes_move = [self.nomes_arquivos.get(c,c) for c in self.camadas_ids[1:]]
        var_disc = ctk.StringVar(value=opcoes_move[0] if opcoes_move else "")
        def _on_prancha_move(nome):
            """Ao selecionar prancha a mover, atualiza o foco automaticamente."""
            self.focar_disciplina(nome)

        ctk.CTkOptionMenu(fps, variable=var_disc,
                          values=opcoes_move if opcoes_move else ["—"],
                          width=180, command=_on_prancha_move
                          ).pack(padx=8, pady=(2,4), anchor="w")
        # Foca na prancha inicial ao abrir o menu
        if opcoes_move: self.after(50, lambda: _on_prancha_move(opcoes_move[0]))

        def get_cid():
            return self.mapa_arquivos.get(var_disc.get())

        # ══════════════════════════════════════════════════════════════════════
        # Abas: Posição | Escala | Alinhar
        # ══════════════════════════════════════════════════════════════════════
        aba_frame = ctk.CTkFrame(jp, fg_color="transparent")
        aba_frame.pack(fill="both", expand=True, padx=14, pady=4)
        aba_frame.grid_rowconfigure(1, weight=1)
        aba_frame.grid_columnconfigure(0, weight=1)

        # Barra de abas
        tab_bar = ctk.CTkFrame(aba_frame, fg_color=("gray82","gray20"), corner_radius=8)
        tab_bar.grid(row=0, column=0, sticky="ew", pady=(0,4))
        content = ctk.CTkScrollableFrame(aba_frame, corner_radius=8, fg_color=("gray92","gray15"))
        content.grid(row=1, column=0, sticky="nsew")

        aba_atual = {"v": "pos"}
        tab_btns  = {}
        ABAS = [("📐 Posição","pos"), ("🔍 Escala","esc"), ("🎯 Alinhar","aln")]

        _aba_builders = {}   # preenchido após defs

        def mostrar_aba(aba_id):
            aba_atual["v"] = aba_id
            for aid, btn in tab_btns.items():
                btn.configure(fg_color=("#2980B9","#1A5276") if aid==aba_id
                              else ("gray75","gray30"))
            for w in content.winfo_children(): w.destroy()
            builder = _aba_builders.get(aba_id)
            if builder: builder(content)

        for lbl, aid in ABAS:
            b = ctk.CTkButton(tab_bar, text=lbl, height=30,
                               fg_color="gray75", hover_color=("#2471A3","#1A5276"),
                               font=ctk.CTkFont(size=11),
                               command=lambda a=aid: mostrar_aba(a))
            b.pack(side="left", expand=True, fill="x", padx=3, pady=4)
            tab_btns[aid] = b

        # ─────────────────────────────────────────────────────────────────────
        def _build_posicao(f):
            """Aba Posição: joystick + passo."""
            ctk.CTkLabel(f, text="Mover a prancha selecionada:",
                         font=ctk.CTkFont(weight="bold")).pack(anchor="w", padx=8, pady=(8,2))

            # Passo
            step_var = ctk.DoubleVar(value=0.01)
            fs = ctk.CTkFrame(f, fg_color="transparent"); fs.pack(anchor="w", padx=8, pady=2)
            ctk.CTkLabel(fs, text="Passo:", font=ctk.CTkFont(size=10)).pack(side="left")
            for lbl, val in [("0.1%",0.001),("0.5%",0.005),("1%",0.01),("5%",0.05)]:
                ctk.CTkButton(fs, text=lbl, width=42, height=22,
                              font=ctk.CTkFont(size=10),
                              fg_color=("gray75","gray35"),
                              command=lambda v=val: step_var.set(v)
                              ).pack(side="left", padx=1)

            def _mover(dx, dy):
                cid = get_cid()
                if not cid: return
                off = self._layer_offset.get(cid,(0.0,0.0))
                self._layer_offset[cid] = (off[0]+dx, off[1]+dy)
                self.marcar_alterado(); self.renderizar_composite()

            # Joystick grid 3×3
            fj = ctk.CTkFrame(f, fg_color="transparent")
            fj.pack(pady=6)
            SZ = 36
            for col in range(3): fj.grid_columnconfigure(col, minsize=SZ+6)
            ctk.CTkButton(fj, text="▲", width=SZ, height=SZ,
                          font=ctk.CTkFont(size=16),
                          command=lambda: _mover(0,-step_var.get())
                          ).grid(row=0, column=1, padx=2, pady=2)
            ctk.CTkButton(fj, text="◀", width=SZ, height=SZ,
                          font=ctk.CTkFont(size=16),
                          command=lambda: _mover(-step_var.get(),0)
                          ).grid(row=1, column=0, padx=2, pady=2)
            ctk.CTkLabel(fj, text="✛", width=SZ, font=ctk.CTkFont(size=18),
                         text_color="gray").grid(row=1, column=1)
            ctk.CTkButton(fj, text="▶", width=SZ, height=SZ,
                          font=ctk.CTkFont(size=16),
                          command=lambda: _mover(step_var.get(),0)
                          ).grid(row=1, column=2, padx=2, pady=2)
            ctk.CTkButton(fj, text="▼", width=SZ, height=SZ,
                          font=ctk.CTkFont(size=16),
                          command=lambda: _mover(0,step_var.get())
                          ).grid(row=2, column=1, padx=2, pady=2)

            ctk.CTkFrame(f, height=1, fg_color="gray").pack(fill="x", padx=8, pady=6)
            def _reset_pos():
                cid = get_cid()
                if cid:
                    self._layer_offset[cid] = (0.0,0.0)
                    self.renderizar_composite()
            ctk.CTkButton(f, text="↺ Resetar posição", height=26,
                          fg_color="transparent", border_width=1,
                          text_color=("gray10","gray90"),
                          command=_reset_pos).pack(fill="x", padx=8, pady=4)

        # ─────────────────────────────────────────────────────────────────────
        def _build_escala(f):
            """Aba Escala: campo de texto + botões rápidos."""
            ctk.CTkLabel(f, text="Escala da prancha selecionada:",
                         font=ctk.CTkFont(weight="bold")).pack(anchor="w", padx=8, pady=(8,4))

            cid0 = get_cid()
            sc_atual = self._layer_scale.get(cid0 or '', 1.0)

            fv = ctk.CTkFrame(f, fg_color="transparent"); fv.pack(fill="x", padx=8, pady=4)
            ctk.CTkLabel(fv, text="Valor:", width=40,
                         font=ctk.CTkFont(size=11)).pack(side="left")
            entry_sc = ctk.CTkEntry(fv, width=80, height=30)
            entry_sc.insert(0, f"{sc_atual:.4f}")
            entry_sc.pack(side="left", padx=4)
            ctk.CTkLabel(fv, text="×", font=ctk.CTkFont(size=12)).pack(side="left")
            ctk.CTkButton(fv, text="Aplicar ↵", width=80, height=30,
                          fg_color="#27AE60", hover_color="#1E8449",
                          command=lambda: _aplicar_entry()).pack(side="left", padx=6)

            def _aplicar_entry():
                cid = get_cid()
                if not cid: return
                try:
                    v = float(entry_sc.get().replace(',','.'))
                    if not 0.05 <= v <= 10.0: raise ValueError()
                    self._apply_scale(cid, v)
                except ValueError:
                    messagebox.showwarning("Valor inválido",
                        "Escala deve ser entre 0.05 e 10.0", parent=jp)

            # Botões rápidos
            ctk.CTkLabel(f, text="Rápido:", font=ctk.CTkFont(size=10),
                         text_color="gray").pack(anchor="w", padx=8, pady=(6,2))
            fg = ctk.CTkFrame(f, fg_color="transparent"); fg.pack(fill="x", padx=8)
            for lbl, v in [("50%",0.5),("75%",0.75),("100%",1.0),
                            ("125%",1.25),("150%",1.5),("200%",2.0)]:
                def _sc(vv=v):
                    cid = get_cid()
                    if cid:
                        self._apply_scale(cid, vv)
                        entry_sc.delete(0,"end")
                        entry_sc.insert(0, f"{vv:.4f}")
                ctk.CTkButton(fg, text=lbl, width=52, height=26,
                              font=ctk.CTkFont(size=10),
                              fg_color=("gray75","gray35"),
                              command=_sc).pack(side="left", padx=1, pady=2)

            ctk.CTkFrame(f, height=1, fg_color="gray").pack(fill="x", padx=8, pady=8)
            def _reset_esc():
                cid = get_cid()
                if cid:
                    self._apply_scale(cid, 1.0)
                    entry_sc.delete(0,"end"); entry_sc.insert(0,"1.0000")
            ctk.CTkButton(f, text="↺ Resetar escala", height=26,
                          fg_color="transparent", border_width=1,
                          text_color=("gray10","gray90"),
                          command=_reset_esc).pack(fill="x", padx=8, pady=4)

        # ─────────────────────────────────────────────────────────────────────
        def _build_alinhar(f):
            """Aba Alinhar: 2 pontos | por linha | automático."""

            # ── Sub-abas ──────────────────────────────────────────────────────
            sub_bar = ctk.CTkFrame(f, fg_color=("gray80","gray25"), corner_radius=6)
            sub_bar.pack(fill="x", padx=6, pady=(8,4))
            sub_content = ctk.CTkFrame(f, fg_color="transparent")
            sub_content.pack(fill="both", expand=True, padx=4)

            sub_btns = {}
            SUBS = [("📍 2 Pontos","pts"),("📏 Por Linha","lin"),("🔍 Auto (AKAZE)","orb")]

            _sub_builders = {}   # preenchido após defs de _build_*

            def mostrar_sub(sid):
                for aid2, b2 in sub_btns.items():
                    b2.configure(fg_color=("#1A5276","#0E2F44") if aid2==sid
                                 else ("gray60","gray30"))
                for w in sub_content.winfo_children(): w.destroy()
                builder = _sub_builders.get(sid)
                if builder: builder(sub_content)

            for lbl2, sid2 in SUBS:
                b2 = ctk.CTkButton(sub_bar, text=lbl2, height=26,
                                   fg_color="gray60", hover_color="#1A5276",
                                   font=ctk.CTkFont(size=10),
                                   command=lambda s=sid2: mostrar_sub(s))
                b2.pack(side="left", expand=True, fill="x", padx=2, pady=3)
                sub_btns[sid2] = b2
            # mostrar_sub called after builders are registered (below)

            # ── Alinhamento por 2 Pontos ──────────────────────────────────────
            def _build_pts(pf):
                ctk.CTkLabel(pf, text="Marque P1 na prancha a mover, P2 no destino:",
                             text_color="gray", font=ctk.CTkFont(size=10),
                             wraplength=360, justify="left").pack(anchor="w", pady=(4,6))

                self._align_p1 = None; self._align_p2 = None
                row_lbl = ctk.CTkFrame(pf, fg_color="transparent"); row_lbl.pack(fill="x")
                lbl_p1 = ctk.CTkLabel(row_lbl, text="P1: —",
                                       font=ctk.CTkFont(size=10), text_color="#E74C3C")
                lbl_p1.pack(side="left", padx=6)
                lbl_p2 = ctk.CTkLabel(row_lbl, text="P2: —",
                                       font=ctk.CTkFont(size=10), text_color="#2980B9")
                lbl_p2.pack(side="left", padx=6)

                def _start_pick(num):
                    self._align_picking = num
                    self.desenho_canvas.configure(cursor="tcross")
                    self.desenho_canvas.delete("pick_hint")
                    cor  = "#E74C3C" if num==1 else "#2980B9"
                    nome = "prancha a mover" if num==1 else "destino (base)"
                    self.desenho_canvas.create_text(
                        self.desenho_canvas.winfo_width()//2, 22,
                        text=f"✛ Marque P{num} na {nome}",
                        fill=cor, font=("Arial",13,"bold"), tags="pick_hint")
                    jp.attributes("-topmost",False)

                def _on_pick(event):
                    if not getattr(self,'_align_picking',None): return
                    cx = self.desenho_canvas.canvasx(event.x)
                    cy = self.desenho_canvas.canvasy(event.y)
                    tag = f"align_p{self._align_picking}"
                    self.desenho_canvas.delete(tag)
                    cor = "#E74C3C" if self._align_picking==1 else "#2980B9"
                    r = 10
                    self.desenho_canvas.create_oval(cx-r,cy-r,cx+r,cy+r,
                        fill=cor, outline="white", width=2, tags=tag)
                    self.desenho_canvas.create_line(cx-r-6,cy,cx+r+6,cy,
                        fill=cor,width=2,tags=tag)
                    self.desenho_canvas.create_line(cx,cy-r-6,cx,cy+r+6,
                        fill=cor,width=2,tags=tag)
                    if self._align_picking==1:
                        self._align_p1=(cx,cy)
                        try: lbl_p1.configure(text=f"P1: ({int(cx)},{int(cy)}) ✅")
                        except: pass
                    else:
                        self._align_p2=(cx,cy)
                        try: lbl_p2.configure(text=f"P2: ({int(cx)},{int(cy)}) ✅")
                        except: pass
                    self._align_picking=None
                    self.desenho_canvas.configure(cursor="arrow")
                    self.desenho_canvas.delete("pick_hint")
                    try: jp.attributes("-topmost",True)
                    except: pass

                self._pick_bid = self.desenho_canvas.bind("<ButtonPress-1>",
                    lambda e: _on_pick(e) if getattr(self,'_align_picking',None)
                              else self.on_canvas_press(e), add=True)

                def _alinhar_pts():
                    if not self._align_p1 or not self._align_p2:
                        messagebox.showwarning("Aviso","Marque P1 e P2 primeiro.",parent=self)
                        return
                    cid=get_cid()
                    if not cid: return
                    dw=max(1,self._base_w*self._render_zoom)
                    dh=max(1,self._base_h*self._render_zoom)
                    dx=(self._align_p2[0]-self._align_p1[0])/dw
                    dy=(self._align_p2[1]-self._align_p1[1])/dh
                    off=self._layer_offset.get(cid,(0,0))
                    self._layer_offset[cid]=(off[0]+dx,off[1]+dy)
                    if not hasattr(self,'_align_anchors'): self._align_anchors={}
                    self._align_anchors[cid]=(self._align_p2[0]/dw,self._align_p2[1]/dh)
                    self.desenho_canvas.delete("align_p1"); self.desenho_canvas.delete("align_p2")
                    self._align_p1=self._align_p2=None
                    try: lbl_p1.configure(text="P1: —"); lbl_p2.configure(text="P2: —")
                    except: pass
                    self._zoom_active = False
                    with self._cache_lock: self._img_cache.clear()
                    self.marcar_alterado(); self.renderizar_composite()

                row_btn=ctk.CTkFrame(pf,fg_color="transparent"); row_btn.pack(fill="x",pady=6)
                ctk.CTkButton(row_btn,text="📍 Marcar P1",width=100,height=28,
                              fg_color="#E74C3C",hover_color="#C0392B",
                              font=ctk.CTkFont(size=10),
                              command=lambda:_start_pick(1)).pack(side="left",padx=2)
                ctk.CTkButton(row_btn,text="📍 Marcar P2",width=100,height=28,
                              fg_color="#2980B9",hover_color="#1A5276",
                              font=ctk.CTkFont(size=10),
                              command=lambda:_start_pick(2)).pack(side="left",padx=2)
                ctk.CTkButton(row_btn,text="⇌ Alinhar",width=80,height=28,
                              fg_color="#27AE60",hover_color="#1E8449",
                              font=ctk.CTkFont(size=10,weight="bold"),
                              command=_alinhar_pts).pack(side="left",padx=4)

            # ── Alinhamento por Linha ─────────────────────────────────────────
            def _build_lin(pf):
                ctk.CTkLabel(pf,
                             text="1. Clique em 2 pontos sobre a prancha a mover\n"
                                  "2. Confirme a linha → programa muda para a base\n"
                                  "3. Clique 2 pontos na prancha base → Alinhar",
                             text_color="gray", font=ctk.CTkFont(size=10),
                             justify="left", wraplength=360).pack(anchor="w",pady=(4,6))

                self._ln_fase    = None    # 'l1_A','l1_B','l2_A','l2_B'
                self._ln_pts     = {}      # {'l1_A':(x,y),'l1_B':...,'l2_A':...,'l2_B':...}
                self._ln_ids     = []      # canvas item ids permanentes

                lbl_fase = ctk.CTkLabel(pf, text="Pronto — clique em 'Iniciar'",
                                         font=ctk.CTkFont(size=10, weight="bold"),
                                         text_color="#2980B9")
                lbl_fase.pack(anchor="w", padx=4, pady=2)

                def _limpar_linhas():
                    for t in ("ln_l1","ln_l2","ln_pt","line_hint"):
                        self.desenho_canvas.delete(t)
                    self._ln_pts={}; self._ln_fase=None

                def _desenhar_linha_canvas(A, B, cor, tag):
                    """Desenha linha com setas e pontos de apoio no canvas."""
                    ax,ay=A; bx,by=B
                    # Linha grossa
                    self.desenho_canvas.create_line(ax,ay,bx,by,
                        fill=cor, width=3, arrow="both",
                        arrowshape=(10,12,5), tags=tag)
                    r=6
                    for px,py in [(ax,ay),(bx,by)]:
                        self.desenho_canvas.create_oval(px-r,py-r,px+r,py+r,
                            fill=cor,outline="white",width=2,tags=tag)

                def _start_fase(fase):
                    """Ativa captura de ponto para uma fase."""
                    self._ln_fase = fase
                    self.desenho_canvas.configure(cursor="tcross")
                    self.desenho_canvas.delete("line_hint")
                    cor  = "#8E44AD" if fase.startswith("l1") else "#27AE60"
                    if fase.endswith("_A"):
                        msg = ("Clique no ponto inicial (A) na prancha a mover"
                               if fase=="l1_A" else
                               "Clique no ponto inicial (C) na prancha base")
                    else:
                        msg = ("Clique no ponto final (B) na prancha a mover"
                               if fase=="l1_B" else
                               "Clique no ponto final (D) na prancha base")
                    # Crosshair grande nas bordas do canvas para guia visual
                    cw = self.desenho_canvas.winfo_width()
                    ch = self.desenho_canvas.winfo_height()
                    self.desenho_canvas.create_text(
                        cw//2, 26,
                        text=f"✛ {msg}", fill=cor,
                        font=("Arial",13,"bold"), tags="line_hint")
                    # Linhas-guia cruzadas (atualizadas via Motion)
                    self.desenho_canvas.create_line(
                        0, ch//2, cw, ch//2,
                        fill=cor, width=1, dash=(4,4), tags="line_hint")
                    self.desenho_canvas.create_line(
                        cw//2, 0, cw//2, ch,
                        fill=cor, width=1, dash=(4,4), tags="line_hint")
                    jp.attributes("-topmost",False)

                def _on_ln_click(event):
                    if not self._ln_fase: return
                    cx=self.desenho_canvas.canvasx(event.x)
                    cy=self.desenho_canvas.canvasy(event.y)
                    fase=self._ln_fase
                    self._ln_pts[fase]=(cx,cy)
                    self._ln_fase=None
                    self.desenho_canvas.configure(cursor="arrow")
                    self.desenho_canvas.delete("line_hint")
                    try: jp.attributes("-topmost",True)
                    except: pass
                    # Marca ponto no canvas
                    cor="#8E44AD" if fase.startswith("l1") else "#27AE60"
                    r=7
                    self.desenho_canvas.create_oval(cx-r,cy-r,cx+r,cy+r,
                        fill=cor,outline="white",width=2,tags="ln_pt")

                    # Avança fluxo automaticamente
                    if fase=="l1_A":
                        lbl_fase.configure(text="✅ Ponto A marcado — marque o ponto B")
                        _start_fase("l1_B")
                    elif fase=="l1_B":
                        # Desenha linha 1
                        A=self._ln_pts.get("l1_A"); B=self._ln_pts.get("l1_B")
                        if A and B:
                            _desenhar_linha_canvas(A,B,"#8E44AD","ln_l1")
                        # Pergunta se OK
                        try: jp.attributes("-topmost",True)
                        except: pass
                        ok=messagebox.askyesno("Linha 1",
                            "A linha na prancha a mover está correta?\\n"
                            "Clique Sim para marcar a linha na prancha base.",
                            parent=jp)
                        if not ok:
                            self.desenho_canvas.delete("ln_l1")
                            self.desenho_canvas.delete("ln_pt")
                            self._ln_pts.pop("l1_A",None); self._ln_pts.pop("l1_B",None)
                            lbl_fase.configure(text="Linha cancelada — inicie novamente")
                            return
                        # Muda para prancha base
                        base_nome=self.nomes_arquivos.get(self.camadas_ids[0],"Base")
                        self.focar_disciplina(base_nome)
                        lbl_fase.configure(text=f"✅ Linha 1 OK — agora marque na prancha base: {base_nome}")
                        _start_fase("l2_A")
                    elif fase=="l2_A":
                        lbl_fase.configure(text="✅ Ponto C marcado — marque o ponto D")
                        _start_fase("l2_B")
                    elif fase=="l2_B":
                        C=self._ln_pts.get("l2_A"); D=self._ln_pts.get("l2_B")
                        if C and D:
                            _desenhar_linha_canvas(C,D,"#27AE60","ln_l2")
                        lbl_fase.configure(text="✅ Duas linhas definidas — clique Alinhar")

                self._ln_bid = self.desenho_canvas.bind("<ButtonPress-1>",
                    lambda e: _on_ln_click(e) if self._ln_fase
                              else self.on_canvas_press(e), add=True)

                def _alinhar_linha():
                    import math
                    cid=get_cid()
                    if not cid:
                        messagebox.showwarning("Aviso","Selecione a prancha.",parent=self); return
                    pts=self._ln_pts
                    if not all(k in pts for k in ("l1_A","l1_B","l2_A","l2_B")):
                        messagebox.showwarning("Aviso","Defina as duas linhas primeiro.",parent=self)
                        return
                    ax,ay=pts["l1_A"]; bx,by=pts["l1_B"]
                    cx,cy=pts["l2_A"]; dx,dy=pts["l2_B"]
                    len1=math.hypot(bx-ax,by-ay)
                    len2=math.hypot(dx-cx,dy-cy)
                    if len1<5:
                        messagebox.showwarning("Aviso","Linha 1 muito curta.",parent=self); return
                    dw=max(1,self._base_w*self._render_zoom)
                    dh=max(1,self._base_h*self._render_zoom)
                    sc_old=self._layer_scale.get(cid,1.0)
                    off_old=self._layer_offset.get(cid,(0.0,0.0))
                    # Escala nova: proporção dos comprimentos das linhas
                    sc_novo=(len2/len1)*sc_old
                    sc_novo=max(0.05,min(10.0,sc_novo))
                    # Coord. normalizada da imagem no ponto A (linha 1, prancha a mover)
                    # canvas_x = off_x*dw + nx_img*dw*sc  →  nx_img=(canvas_x/dw - off_x)/sc
                    nx_img_A=(ax/dw - off_old[0]) / max(0.0001, sc_old)
                    ny_img_A=(ay/dh - off_old[1]) / max(0.0001, sc_old)
                    # Novo offset: ponto A da imagem deve coincidir com C (linha 2, base)
                    # cx = off_x_new*dw + nx_img_A*dw*sc_novo
                    off_x=cx/dw - nx_img_A*sc_novo
                    off_y=cy/dh - ny_img_A*sc_novo
                    self._layer_scale[cid]=sc_novo
                    self._layer_offset[cid]=(off_x,off_y)
                    if not hasattr(self,'_align_anchors'): self._align_anchors={}
                    self._align_anchors[cid]=(cx/dw,cy/dh)
                    with self._cache_lock: self._img_cache.clear()
                    self._zoom_active = False   # garante LANCZOS no render de alinhamento
                    self.marcar_alterado(); self.renderizar_composite()
                    # Limpa canvas
                    for t in ("ln_l1","ln_l2","ln_pt","line_hint"):
                        self.desenho_canvas.delete(t)
                    self._ln_pts={}
                    try: lbl_fase.configure(
                        text=f"✅ Alinhado! Escala: {sc_novo:.3f}×",
                        text_color="#27AE60")
                    except: pass

                row_btn2=ctk.CTkFrame(pf,fg_color="transparent"); row_btn2.pack(fill="x",pady=4)
                ctk.CTkButton(row_btn2,text="▶ Iniciar",width=80,height=28,
                              fg_color="#8E44AD",hover_color="#6C3483",
                              font=ctk.CTkFont(size=10,weight="bold"),
                              command=lambda:_start_fase("l1_A")).pack(side="left",padx=2)
                ctk.CTkButton(row_btn2,text="↺ Limpar",width=72,height=28,
                              fg_color="gray",
                              font=ctk.CTkFont(size=10),
                              command=_limpar_linhas).pack(side="left",padx=2)
                ctk.CTkButton(row_btn2,text="⇌ Alinhar",width=80,height=28,
                              fg_color="#27AE60",hover_color="#1E8449",
                              font=ctk.CTkFont(size=10,weight="bold"),
                              command=_alinhar_linha).pack(side="left",padx=4)

            # ── Alinhamento Automático ────────────────────────────────────────
            def _build_orb(pf):
                ctk.CTkLabel(pf,
                             text="Detecta geometrias comuns entre as pranchas\\n"
                                  "e estima translação automaticamente (OpenCV AKAZE).",
                             text_color="gray",font=ctk.CTkFont(size=10),
                             justify="left",wraplength=360).pack(anchor="w",pady=(4,8))
                lbl_orb=ctk.CTkLabel(pf,text="",font=ctk.CTkFont(size=10))
                lbl_orb.pack(anchor="w",padx=4)
                pb_orb=ctk.CTkProgressBar(pf,width=300,height=6,
                                           fg_color=("gray80","gray30"),
                                           progress_color="#2980B9")
                pb_orb.pack(fill="x",padx=4,pady=2); pb_orb.set(0)

                def _auto_align():
                    cid=get_cid()
                    if not cid:
                        messagebox.showwarning("Aviso","Selecione a prancha.",parent=self); return
                    base_cid=self.camadas_ids[0]
                    img_base=self.camadas_pdf.get(base_cid,{}).get('pil_original')
                    img_move=self.camadas_pdf.get(cid,{}).get('pil_original')
                    if not img_base or not img_move:
                        messagebox.showwarning("Aviso","Aguarde o carregamento.",parent=self); return

                    def _upd(txt, cor="#2980B9", prog=None):
                        def _f():
                            try:
                                lbl_orb.configure(text=txt, text_color=cor)
                                if prog is not None: pb_orb.set(prog)
                            except: pass
                        self.after(0, _f)

                    _upd("⏳ Pré-processando imagens...", prog=0.1)

                    import threading
                    def _run():
                        try:
                            import cv2, numpy as np

                            # ── Pré-processamento: CLAHE melhora contraste em CAD ──────────
                            def _prep(pil_img, mx=700):
                                """Reduz, converte para cinza e aplica CLAHE."""
                                i2 = pil_img.copy(); i2.thumbnail((mx, mx))
                                gray = cv2.cvtColor(np.array(i2.convert('RGB')), cv2.COLOR_RGB2GRAY)
                                clahe = cv2.createCLAHE(clipLimit=3.0, tileGridSize=(8, 8))
                                return clahe.apply(gray), i2.size

                            _upd("⏳ Pré-processando imagens (CLAHE)...", prog=0.15)
                            gb, sb = _prep(img_base)
                            gm, sm = _prep(img_move)

                            # ── AKAZE: melhor que ORB para plantas técnicas ────────────────
                            # AKAZE detecta features em múltiplas escalas com maior precisão
                            # para imagens com linhas retas e poucos gradientes (CAD/BIM)
                            _upd("⏳ Detectando features (AKAZE)...", prog=0.30)
                            try:
                                akaze = cv2.AKAZE_create()
                                kp1, d1 = akaze.detectAndCompute(gb, None)
                                kp2, d2 = akaze.detectAndCompute(gm, None)
                                detector_name = "AKAZE"
                            except Exception:
                                # Fallback para ORB se AKAZE falhar
                                orb = cv2.ORB_create(nfeatures=3000, scaleFactor=1.2, nlevels=8)
                                kp1, d1 = orb.detectAndCompute(gb, None)
                                kp2, d2 = orb.detectAndCompute(gm, None)
                                detector_name = "ORB"

                            n1 = len(kp1) if kp1 else 0
                            n2 = len(kp2) if kp2 else 0
                            if d1 is None or d2 is None or n1 < 15 or n2 < 15:
                                _upd(f"❌ Poucos features ({n1}, {n2}) — "
                                     "use alinhamento por linha.", "#E74C3C", prog=0)
                                return

                            # ── Lowe's ratio test (mais robusto que crossCheck) ───────────
                            _upd(f"⏳ Calculando correspondências ({detector_name})...", prog=0.50)
                            norm = cv2.NORM_HAMMING  # funciona para AKAZE e ORB
                            bf = cv2.BFMatcher(norm, crossCheck=False)
                            raw = bf.knnMatch(d1, d2, k=2)
                            good = []
                            for pair in raw:
                                if len(pair) == 2:
                                    m, n = pair
                                    if m.distance < 0.75 * n.distance:
                                        good.append(m)

                            if len(good) < 8:
                                _upd(f"❌ Apenas {len(good)} matches válidos — "
                                     "tente alinhamento por linha.", "#E74C3C", prog=0)
                                return

                            _upd("⏳ Calculando transformação afim (RANSAC)...", prog=0.70)

                            src_pts = np.float32([kp1[m.queryIdx].pt for m in good]).reshape(-1, 1, 2)
                            dst_pts = np.float32([kp2[m.trainIdx].pt for m in good]).reshape(-1, 1, 2)

                            # ── estimateAffinePartial2D em vez de findHomography ───────────
                            # Plantas CAD não têm distorção de perspectiva.
                            # Transformação afim parcial (4 DOF: escala uniforme +
                            # rotação + translação X/Y) é matematicamente mais correta
                            # e produz resultados muito mais estáveis que homografia (8 DOF).
                            M, inliers = cv2.estimateAffinePartial2D(
                                dst_pts, src_pts,
                                method=cv2.RANSAC,
                                ransacReprojThreshold=5.0,
                                maxIters=2000,
                                confidence=0.99
                            )

                            if M is None:
                                _upd("❌ Transformação afim falhou — "
                                     "tente alinhamento por linha.", "#E74C3C", prog=0)
                                return

                            # ── Extrai escala e translação da matriz afim 2×3 ─────────────
                            # M = [[a, -b, tx],   onde a = sc*cos(θ), b = sc*sin(θ)
                            #       [b,  a, ty]]
                            sc_x = float(np.sqrt(M[0, 0]**2 + M[1, 0]**2))
                            sc_y = float(np.sqrt(M[0, 1]**2 + M[1, 1]**2))
                            sc_est = float((sc_x + sc_y) / 2.0)
                            sc_est = max(0.5, min(2.0, sc_est))  # limita a range razoável

                            tx = float(M[0, 2]); ty = float(M[1, 2])

                            # Escala de volta para coords da imagem original
                            sx = img_base.size[0] / sb[0]
                            sy = img_base.size[1] / sb[1]
                            tx *= sx; ty *= sy

                            # Converte translação para coordenadas normalizadas (0-1)
                            dw = max(1, img_base.size[0] * self._render_zoom)
                            dh = max(1, img_base.size[1] * self._render_zoom)
                            nx_off = tx / dw
                            ny_off = ty / dh

                            # Confiança: % de inliers
                            n_in = int(inliers.sum()) if inliers is not None else len(good)
                            conf = n_in / max(1, len(good))

                            if conf < 0.25:
                                _upd(f"❌ Confiança muito baixa ({conf:.0%}) — "
                                     "pranchas muito diferentes.", "#E74C3C", prog=0)
                                return

                            if abs(nx_off) > 0.8 or abs(ny_off) > 0.8:
                                _upd("⚠️ Offset calculado muito grande — "
                                     "tente alinhamento por linha.", "#F39C12", prog=0)
                                return

                            def _apply(nx=nx_off, ny=ny_off,
                                       n=n_in, sc=sc_est, c=conf, det=detector_name):
                                off = self._layer_offset.get(cid, (0, 0))
                                self._layer_offset[cid] = (off[0] + nx, off[1] + ny)
                                if abs(sc - 1.0) > 0.02:
                                    self._layer_scale[cid] = sc
                                with self._cache_lock: self._img_cache.clear()
                                self.marcar_alterado(); self.renderizar_composite()
                                try:
                                    lbl_orb.configure(
                                        text=f"✅ Alinhado ({det})! {n} inliers | "
                                             f"confiança {c:.0%}"
                                             + (f" | escala {sc:.3f}×" if abs(sc-1)>0.02 else ""),
                                        text_color="#27AE60")
                                    pb_orb.set(1.0)
                                except: pass
                            self.after(0, _apply)

                        except ImportError:
                            _upd("❌ pip install opencv-python", "#E74C3C", prog=0)
                        except Exception as ex:
                            _upd(f"❌ {str(ex)[:70]}", "#E74C3C", prog=0)
                    threading.Thread(daemon=True, target=_run).start()

                ctk.CTkButton(pf,text="🔍 Alinhar Automaticamente",height=32,
                              fg_color=("#1A5276","#154360"),
                              hover_color=("#154360","#0E2F44"),
                              font=ctk.CTkFont(size=11,weight="bold"),
                              command=_auto_align).pack(fill="x",pady=4,padx=4)

            # Registra builders e inicializa sub-aba padrão
            _sub_builders["pts"] = _build_pts
            _sub_builders["lin"] = _build_lin
            _sub_builders["orb"] = _build_orb
            mostrar_sub("pts")

        # Registra builders das abas principais e inicializa
        _aba_builders["pos"] = _build_posicao
        _aba_builders["esc"] = _build_escala
        _aba_builders["aln"] = _build_alinhar
        mostrar_aba("pos")

        # ─────────────────────────────────────────────────────────────────────
        # Botão Resetar tudo (fora das abas)
        ctk.CTkFrame(jp, height=1, fg_color="gray").pack(fill="x", padx=14, pady=4)
        def _reset_all():
            self._layer_offset.clear()
            self._layer_scale.clear()
            with self._cache_lock: self._img_cache.clear()
            self.renderizar_composite()
        ctk.CTkButton(jp,text="↺ Resetar Tudo (offset e escala)",height=26,
                      fg_color="transparent",border_width=1,
                      text_color=("gray10","gray90"),
                      hover_color=("gray80","gray30"),
                      command=_reset_all).pack(fill="x",padx=14,pady=(0,8))

        # Limpeza ao fechar
        def on_close():
            for t in ("align_p1","align_p2","pick_hint","ln_l1","ln_l2",
                      "ln_pt","line_hint","line_preview"):
                self.desenho_canvas.delete(t)
            self._align_picking=None; self._ln_fase=None
            self.desenho_canvas.configure(cursor="arrow")
            for attr in ('_pick_bid','_ln_bid'):
                try:
                    bid=getattr(self,attr,None)
                    ev={"_pick_bid":"<ButtonPress-1>",
                        "_ln_bid":"<ButtonPress-1>"}.get(attr,"")
                    if bid and ev: self.desenho_canvas.unbind(ev,bid)
                except: pass
            jp.destroy()
        jp.protocol("WM_DELETE_WINDOW",on_close)

    def _apply_offset(self, cid, nx, ny):
        self._layer_offset[cid]=(float(nx),float(ny))
        self.marcar_alterado(); self.renderizar_composite()

    def _apply_scale(self, cid, sc):
        """Escala preservando pivot de alinhamento."""
        old_sc=self._layer_scale.get(cid,1.0)
        new_sc=max(0.05,float(sc))
        if abs(new_sc-old_sc)<0.0001: return
        anchor=getattr(self,'_align_anchors',{}).get(cid)
        if anchor:
            nx_a,ny_a=anchor
            off=self._layer_offset.get(cid,(0,0))
            self._layer_offset[cid]=(off[0]+nx_a*(old_sc-new_sc),
                                      off[1]+ny_a*(old_sc-new_sc))
        self._layer_scale[cid]=new_sc
        with self._cache_lock: self._img_cache.clear()
        self.marcar_alterado(); self.renderizar_composite()


    def _configurar_chave_api(self):
        """Dialog para configurar a chave Groq API em runtime."""
        jk = ctk.CTkToplevel(self)
        jk.title("Configurar Chave Groq API")
        self._centrar_janela(jk, 500, 260); jk.attributes("-topmost", True); jk.grab_set()

        ctk.CTkLabel(jk, text="🔑 Configurar Chave Groq API",
                     font=ctk.CTkFont(size=16, weight="bold")).pack(pady=(16,2))
        ctk.CTkLabel(jk, text="Gratuito em: https://console.groq.com/keys  —  14.400 req/dia",
                     text_color="gray", font=ctk.CTkFont(size=11)).pack()

        ef = ctk.CTkFrame(jk, fg_color="transparent"); ef.pack(fill="x", padx=20, pady=12)
        entry = ctk.CTkEntry(ef, placeholder_text="gsk_...", show="*", height=36)
        # Pré-preenche se já tiver chave salva
        saved = self.config_app.get('groq_api_key', '')
        if saved: entry.insert(0, saved)
        entry.pack(fill="x")

        row_vis = ctk.CTkFrame(ef, fg_color="transparent"); row_vis.pack(fill="x", pady=4)
        ctk.CTkButton(row_vis, text="👁 Mostrar/Ocultar", width=130, height=24,
                      fg_color="gray",
                      command=lambda: entry.configure(
                          show="" if entry.cget("show") == "*" else "*")
                      ).pack(side="left")
        lbl_ok = ctk.CTkLabel(row_vis, text="", font=ctk.CTkFont(size=11))
        lbl_ok.pack(side="left", padx=10)

        def salvar():
            k = entry.get().strip()
            if not k or len(k) < 10:
                lbl_ok.configure(text="⚠ Digite uma chave válida", text_color="#E74C3C")
                return
            # Salva no config_app E na variável global
            global _GROQ_API_KEY
            _GROQ_API_KEY = k
            self.config_app['groq_api_key'] = k
            self.salvar_config()
            lbl_ok.configure(text="✅ Chave salva!", text_color="#27AE60")
            jk.after(800, jk.destroy)

        ctk.CTkButton(jk, text="✅ Salvar Chave", height=36,
                      fg_color="#27AE60", hover_color="#1E8449",
                      font=ctk.CTkFont(weight="bold"),
                      command=salvar).pack(fill="x", padx=20, pady=4)
        ctk.CTkButton(jk, text="Cancelar", height=28, fg_color="gray",
                      command=jk.destroy).pack(pady=2)


    # ══════════════════════════════════════════════════════════════════════════
    # ZOOM POR ÁREA (retângulo)
    # ══════════════════════════════════════════════════════════════════════════

    def _iniciar_zoom_area(self):
        """Ativa modo de zoom por retângulo."""
        self._zoom_area_mode = True
        self._zoom_area_start = None
        self._zoom_area_rect  = None
        self.desenho_canvas.configure(cursor="crosshair")
        # Hint
        self.desenho_canvas.delete("zoom_hint")
        cw = self.desenho_canvas.winfo_width()
        self.desenho_canvas.create_text(
            cw//2, 20, text="🔲 Arraste para definir área de zoom",
            fill="#2980B9", font=("Arial",12,"bold"), tags="zoom_hint")
        # Binds temporários
        self._za_b1 = self.desenho_canvas.bind("<ButtonPress-1>",
            lambda e: self._za_press(e), add=True)
        self._za_bm = self.desenho_canvas.bind("<B1-Motion>",
            lambda e: self._za_drag(e), add=True)
        self._za_br = self.desenho_canvas.bind("<ButtonRelease-1>",
            lambda e: self._za_release(e), add=True)

    def _za_press(self, e):
        if not getattr(self,'_zoom_area_mode',False): return
        self._zoom_area_start = (
            self.desenho_canvas.canvasx(e.x),
            self.desenho_canvas.canvasy(e.y))
        if self._zoom_area_rect:
            try: self.desenho_canvas.delete(self._zoom_area_rect)
            except: pass

    def _za_drag(self, e):
        if not getattr(self,'_zoom_area_mode',False) or not self._zoom_area_start: return
        x0,y0 = self._zoom_area_start
        x1 = self.desenho_canvas.canvasx(e.x)
        y1 = self.desenho_canvas.canvasy(e.y)
        if self._zoom_area_rect:
            try: self.desenho_canvas.delete(self._zoom_area_rect)
            except: pass
        self._zoom_area_rect = self.desenho_canvas.create_rectangle(
            x0,y0,x1,y1, outline="#2980B9", width=2, dash=(6,3), tags="zoom_area_rect")

    def _za_release(self, e):
        if not getattr(self,'_zoom_area_mode',False) or not self._zoom_area_start: return
        x0,y0 = self._zoom_area_start
        x1 = self.desenho_canvas.canvasx(e.x)
        y1 = self.desenho_canvas.canvasy(e.y)
        # Limpa
        self._zoom_area_mode = False
        self._zoom_area_start = None
        self.desenho_canvas.configure(cursor="arrow")
        self.desenho_canvas.delete("zoom_hint")
        self.desenho_canvas.delete("zoom_area_rect")
        for attr in ('_za_b1','_za_bm','_za_br'):
            bid = getattr(self,attr,None)
            if bid:
                ev = {"_za_b1":"<ButtonPress-1>","_za_bm":"<B1-Motion>",
                      "_za_br":"<ButtonRelease-1>"}.get(attr,"")
                try: self.desenho_canvas.unbind(ev,bid)
                except: pass
        # Calcula zoom
        rw = abs(x1-x0); rh = abs(y1-y0)
        if rw < 10 or rh < 10: return
        cw = self.desenho_canvas.winfo_width()
        ch = self.desenho_canvas.winfo_height()
        zx = cw / rw; zy = ch / rh
        novo_zoom = self._render_zoom * min(zx, zy) * 0.92
        novo_zoom = max(0.05, min(20.0, novo_zoom))
        # Centro da área selecionada
        cx = (x0+x1)/2; cy = (y0+y1)/2
        nx = cx / max(1, self._base_w * self._render_zoom)
        ny = cy / max(1, self._base_h * self._render_zoom)
        self._render_zoom = novo_zoom
        with self._cache_lock: self._img_cache.clear()
        self.renderizar_composite()
        dw = self._base_w * self._render_zoom
        dh = self._base_h * self._render_zoom
        self.desenho_canvas.xview_moveto(max(0, (nx*dw - cw/2)/max(1,dw)))
        self.desenho_canvas.yview_moveto(max(0, (ny*dh - ch/2)/max(1,dh)))

