    def _stream_analise_ia(self, janela, disciplina, focos, ctx_extra,
                           lbl_status, btn_iniciar, pb,
                           add_log_text, add_log_conflito, state):
        """
        Análise IA via Groq.
        - PDF: envia imagem renderizada para llama-3.2-11b-vision-preview (visão)
        - Extrai também texto do PDF via pymupdf para contexto adicional
        Retorna conflitos parseados com botão Criar Apontamento.
        """
        import threading, json, urllib.request, urllib.error, base64
        from io import BytesIO

        # Lê chave em tempo de execução (config > global > placeholder)
        # Prioridade: 1) chave hardcoded no código, 2) chave salva via menu
        _hc = _GROQ_API_KEY if _GROQ_API_KEY not in ("", None) else ""
        _cfg = self.config_app.get('groq_api_key', '').strip()
        chave = _hc or _cfg
        if not chave:
            # Abre dialog de configuração inline
            pb.stop(); state['running'] = False
            btn_iniciar.configure(state="normal", text="🚀 Iniciar Análise")
            if messagebox.askyesno("Chave Groq não configurada",
                "A chave Groq API não está configurada.\n\n"
                "Deseja configurar agora? (Gratuito em console.groq.com)",
                parent=janela):
                self._configurar_chave_api()
            return

        cid = self.mapa_arquivos.get(disciplina, self.camada_fundo_id)

        def upd(msg, cor="#2980B9"):
            lbl_status.configure(text=msg, text_color=cor)
            janela.update_idletasks()

        # ── PASSO 1: Captura imagem da prancha renderizada ────────────────────
        upd("📸 Capturando prancha...")
        img_b64 = None
        img_pil = None

        # Usa a imagem PIL já renderizada (maior qualidade que screenshot)
        cam = self.camadas_pdf.get(cid, {})
        pil_orig = cam.get('pil_original')

        if pil_orig is not None:
            # Redimensiona para tamanho adequado para visão (max 1024px)
            img_send = pil_orig.copy()
            img_send.thumbnail((1024, 1024))
            buf = BytesIO()
            img_send.save(buf, format="JPEG", quality=85)
            img_b64 = base64.b64encode(buf.getvalue()).decode()
            img_pil = pil_orig
        else:
            # Fallback: screenshot do canvas
            try:
                rx = self.desenho_canvas.winfo_rootx()
                ry = self.desenho_canvas.winfo_rooty()
                rw = self.desenho_canvas.winfo_width()
                rh = self.desenho_canvas.winfo_height()
                img_pil = ImageGrab.grab(bbox=(rx, ry, rx+rw, ry+rh))
                img_send = img_pil.copy(); img_send.thumbnail((1024,1024))
                buf = BytesIO(); img_send.save(buf, format="JPEG", quality=85)
                img_b64 = base64.b64encode(buf.getvalue()).decode()
            except Exception as ex:
                upd(f"⚠ Imagem indisponível: {ex}", "#F39C12")

        n_txt_total = 0

        # ── PASSO 2: Extrai texto do PDF via pymupdf (se disponível) ─────────
        upd("📄 Extraindo texto do PDF...")
        texto_pdf = ""
        try:
            if HAS_FITZ:
                path = cam.get('path', '')
                if path and path.lower().endswith('.pdf'):
                    doc = fitz.open(path)
                    try:
                        page = doc[cam.get('page_num', 0)]
                        blocks = page.get_text("blocks")
                        blocks_sorted = sorted(blocks, key=lambda b: (round(b[1]/20)*20, b[0]))
                        linhas = []
                        for b in blocks_sorted:
                            txt = b[4].strip().replace('\n', ' ')
                            if len(txt) > 2:
                                linhas.append(txt)
                        texto_pdf = '\n'.join(linhas)[:4000]
                        n_txt_total = len(linhas)
                    finally:
                        doc.close()
        except Exception: pass

        self.after(0, lambda n=n_txt_total: add_log_text(
            f"ℹ️ Prancha carregada: {n} palavras extraídas do PDF.",
            ("gray50","gray50")))

        # ── PASSO 3: Contexto do projeto ──────────────────────────────────────
        issues_ex = [f"{i['id']}: {i['titulo']}" for i in self.lista_issues][:8]

        ctx_projeto = (
            f"Projeto: {self.meta_empreendimento} | Etapa: {self.meta_etapa}\n"
            f"Disciplina analisada: {disciplina}"
        )
        if texto_pdf.strip():
            # Resume o texto extraído (primeiras 800 chars das mais relevantes linhas)
            linhas_relevantes = [l.strip() for l in texto_pdf.split("\n")
                                  if len(l.strip()) > 4][:60]
            ctx_projeto += f"\n\nTEXTO EXTRAÍDO DO PDF:\n" + "\n".join(linhas_relevantes[:40])
        if issues_ex:
            ctx_projeto += "\n\nAPONTAMENTOS JÁ EXISTENTES (NÃO repetir):\n" + "\n".join(f"  - {i}" for i in issues_ex)
        if ctx_extra:
            ctx_projeto += f"\n\nOBSERVAÇÕES DO ANALISTA:\n{ctx_extra}"

        # ── PASSO 4: Focos selecionados ───────────────────────────────────────
        focos_lista = []
        if focos.get('conflitos'):    focos_lista.append("conflitos visuais e inconsistências")
        if focos.get('nbr'):          focos_lista.append("conformidade com normas NBR brasileiras")
        if focos.get('texto'):        focos_lista.append("qualidade de texto, carimbo e tabelas")
        if focos.get('apontamentos'): focos_lista.append("sugestão de apontamentos de coordenação")

        ctx_disc = self._prompt_disciplina(disciplina)

        # ── PASSO 5: Monta prompt ─────────────────────────────────────────────
        system_msg = (
            "Você é um coordenador BIM/CAD brasileiro sênior, especialista em "
            "compatibilização de projetos de engenharia e arquitetura.\n\n"
            f"{ctx_disc}\n\n"
            "REGRAS DE QUALIDADE:\n"
            "1. Analise a imagem da prancha com atenção. O que você vê é o projeto real.\n"
            "2. Use o texto extraído do PDF como referência adicional.\n"
            "3. Somente reporte problemas que você consegue CONFIRMAR visualmente ou pelo texto.\n"
            "4. Cite elementos específicos que você vê na prancha (ex: 'a tabela no canto inferior direito').\n"
            "5. Prefira 1 apontamento real a 5 especulativos.\n"
            "6. Se o projeto estiver em conformidade, diga isso claramente."
        )

        user_msg = (
            f"Analise a prancha de projeto abaixo. Foco: {', '.join(focos_lista)}.\n\n"
            f"{ctx_projeto}\n\n"
            "Para cada problema CONFIRMADO, use este formato exato:\n\n"
            "[CONFLITO]\n"
            "TITULO: título objetivo (máx 60 chars)\n"
            "DESCRICAO: descrição técnica citando o que você vê na imagem/texto\n"
            "PRIORIDADE: Crítica | Média | Observação\n"
            "TIPO: Interferência entre Disciplinas | Falha Gráfica / Modelagem | "
            "Não atendimento à Diretrizes e Normas | Ausência de Informação / Detalhe | Melhoria / Otimização\n"
            f"DISCIPLINA: {disciplina}\n"
            "[/CONFLITO]\n\n"
            "Estrutura: 1) análise geral, 2) conflitos confirmados, 3) conclusão.\n"
            "Máximo 5 conflitos. Português técnico."
        )

        upd("☁️ Enviando para Groq (visão)...")

        def chamar_api():
            url = "https://api.groq.com/openai/v1/chat/completions"

            # Monta mensagem com imagem (se disponível)
            user_content = []
            if img_b64:
                user_content.append({
                    "type": "image_url",
                    "image_url": {
                        "url": f"data:image/jpeg;base64,{img_b64}"
                    }
                })
            user_content.append({"type": "text", "text": user_msg})

            # Usa meta-llama/llama-4-scout-17b-16e-instruct — suporte a visão no plano gratuito Groq
            # Fallback: llama-3.3-70b-versatile (texto puro, sem imagem)
            model = "meta-llama/llama-4-scout-17b-16e-instruct"

            payload = json.dumps({
                "model": model,
                "messages": [
                    {"role": "system", "content": system_msg},
                    {"role": "user",   "content": user_content if img_b64 else user_msg}
                ],
                "temperature": 0.1,
                "max_tokens": 1800
            }).encode()

            req = urllib.request.Request(
                url, data=payload,
                headers={
                    "Content-Type": "application/json",
                    "Authorization": f"Bearer {chave}",
                    "User-Agent": "Mozilla/5.0 (compatible; Auria/0.1)"
                }, method="POST")

            dots = [0]
            def _tick():
                if state.get('running'):
                    dots[0] = (dots[0] % 3) + 1
                    modelo_label = "Llama Vision" if img_b64 else "Llama 3.3"
                    self.after(0, lambda d=dots[0], ml=modelo_label:
                               upd(f"🧠 {ml} analisando" + "." * d))
                    self.after(900, _tick)
            self.after(900, _tick)

            try:
                with urllib.request.urlopen(req, timeout=90) as resp:
                    result = json.loads(resp.read().decode())
                texto = (result.get("choices",[{}])[0]
                               .get("message",{}).get("content",""))
                if not texto:
                    self.after(0, lambda: _finalizar(False, "Resposta vazia."))
                    return
                self.after(0, lambda t=texto: _exibir(t))

            except urllib.error.HTTPError as he:
                code = he.code
                try:    err = he.read().decode()[:300]
                except: err = ""
                msg = (
                    "Limite de requisições (429).\nAguarde 1 minuto e tente novamente."
                    if code == 429 else
                    f"Chave inválida (401).\nDetalhe: {err[:100]}\nVerifique em console.groq.com"
                    if code == 401 else
                    f"Erro HTTP {code}: {err}")
                self.after(0, lambda m=msg: _finalizar(False, m))
            except Exception as ex:
                self.after(0, lambda m=str(ex): _finalizar(False, m))

        def _exibir(texto):
            partes = texto.split("[CONFLITO]")
            for linha in partes[0].strip().split("\n"):
                if linha.strip(): add_log_text(linha.strip())
            for parte in partes[1:]:
                if "[/CONFLITO]" not in parte: continue
                bloco, resto = parte.split("[/CONFLITO]", 1)
                def gf(b, n):
                    for ln in b.split("\n"):
                        if ln.startswith(f"{n}:"): return ln[len(f"{n}:"):].strip()
                    return ""
                titulo  = gf(bloco, "TITULO")
                desc    = gf(bloco, "DESCRICAO")
                prio    = gf(bloco, "PRIORIDADE")
                tipo    = gf(bloco, "TIPO")
                disc_ap = gf(bloco, "DISCIPLINA") or disciplina
                if titulo: add_log_conflito(titulo, desc, prio, tipo, disc_ap)
                for linha in resto.strip().split("\n"):
                    if linha.strip(): add_log_text(linha.strip())
            _finalizar(True)

        def _finalizar(ok, msg=""):
            pb.stop(); state['running'] = False
            btn_iniciar.configure(state="normal", text="🚀 Nova Análise")
            if ok:
                upd("✅ Análise concluída!", "#27AE60")
                add_log_text(
                    "─── Clique em 📍 Criar nos conflitos para gerar apontamentos. ───",
                    ("#27AE60","#27AE60"))
            else:
                upd(f"❌ {msg[:80]}", "#E74C3C")
                add_log_text(f"Erro: {msg}", "#E74C3C")

        threading.Thread(daemon=True, target=chamar_api).start()


    def abrir_analise_ia(self):
        if not self.camadas_ids:
            messagebox.showwarning("Aviso",
                "Carregue pelo menos um arquivo DXF antes de usar a análise IA.",
                parent=self)
            return

        ji, _ji_c = self._criar_popup(
            "Análise IA — Auria", 600, 720, "🤖",
            btn_id="analise_ia")
        ji = _ji_c  # usa content frame

        # ── Cabeçalho ──────────────────────────────────────────────────────
        ctk.CTkLabel(ji, text="🤖 Análise Inteligente de Projeto",
                     font=ctk.CTkFont(size=17, weight="bold")).pack(pady=(16,2))
        ctk.CTkLabel(ji, text="Powered by Groq  •  Llama 4  •  Gratuito",
                     text_color="gray", font=ctk.CTkFont(size=10)).pack(pady=(0,8))

        # ── Corpo scrollável (config) ───────────────────────────────────────
        body = ctk.CTkScrollableFrame(ji, height=230, fg_color="transparent")
        body.pack(fill="x", padx=16, pady=0)

        ff = ctk.CTkFrame(body, corner_radius=8)
        ff.pack(fill="x", pady=4, ipadx=8, ipady=6)
        ctk.CTkLabel(ff, text="O que analisar:",
                     font=ctk.CTkFont(weight="bold")).pack(anchor="w", pady=(2,4))
        checks = {}
        for key, label in [
            ("conflitos",    "🔴 Conflitos visuais entre elementos"),
            ("nbr",          "📐 Conformidade com normas NBR"),
            ("apontamentos", "📍 Sugerir apontamentos automáticos"),
            ("texto",        "📄 Texto, carimbo e tabelas"),
        ]:
            v = ctk.IntVar(value=1)
            ctk.CTkCheckBox(ff, text=label, variable=v).pack(anchor="w", pady=2)
            checks[key] = v

        fd = ctk.CTkFrame(body, corner_radius=8)
        fd.pack(fill="x", pady=4, ipadx=8, ipady=6)
        ctk.CTkLabel(fd, text="Prancha/Disciplina:",
                     font=ctk.CTkFont(weight="bold")).pack(anchor="w", pady=(2,2))
        disc_opts = list(self.mapa_arquivos.keys()) or ["Nenhuma"]
        cm_disc = ctk.CTkComboBox(fd, values=disc_opts)
        cm_disc.set(self.disciplina_ativa or disc_opts[0])
        cm_disc.pack(fill="x", pady=(0,2))

        fc2 = ctk.CTkFrame(body, corner_radius=8)
        fc2.pack(fill="x", pady=4, ipadx=8, ipady=6)
        ctk.CTkLabel(fc2, text="Observações para a IA (opcional):",
                     font=ctk.CTkFont(weight="bold")).pack(anchor="w")
        tb_ctx = ctk.CTkTextbox(fc2, height=46)
        tb_ctx.pack(fill="x", pady=(4,2))

        # ── Barra de progresso ─────────────────────────────────────────────
        pb = ctk.CTkProgressBar(ji, mode="indeterminate", height=6)
        pb.pack(fill="x", padx=16, pady=(8,0))
        pb.set(0)

        lbl_status = ctk.CTkLabel(ji, text="Pronto.",
                                  text_color="gray", font=ctk.CTkFont(size=11))
        lbl_status.pack(pady=(2,4))

        # ── Log da IA (streaming) ──────────────────────────────────────────
        ctk.CTkLabel(ji, text="📋 Log da Análise:",
                     font=ctk.CTkFont(weight="bold", size=11)).pack(anchor="w", padx=16)
        log_frame = ctk.CTkScrollableFrame(ji, fg_color=("gray92","gray12"),
                                           corner_radius=6)
        log_frame.pack(fill="both", expand=True, padx=16, pady=(2,8))

        # ── Botão iniciar ──────────────────────────────────────────────────
        btn_frame = ctk.CTkFrame(ji, fg_color="transparent", height=52)
        btn_frame.pack(fill="x", padx=16, pady=(0,12))
        btn_frame.pack_propagate(False)
        btn_iniciar = ctk.CTkButton(
            btn_frame, text="🚀 Iniciar Análise", height=40,
            fg_color=("#8E44AD","#6C3483"), hover_color=("#7D3C98","#5B2C6F"),
            font=ctk.CTkFont(size=13, weight="bold"))
        btn_iniciar.pack(fill="x")

        # Estado compartilhado para o log
        state = {'running': False}

        def _add_log_text(txt, color=("gray20","gray80")):
            """Adiciona linha de texto simples ao log."""
            ctk.CTkLabel(log_frame, text=txt, anchor="w", justify="left",
                         wraplength=480, text_color=color,
                         font=ctk.CTkFont(size=10)).pack(anchor="w", pady=1, padx=4)
            log_frame._parent_canvas.yview_moveto(1.0)

        def _add_log_conflito(titulo, descricao, prio, tipo, disc):
            """Adiciona um conflito encontrado com botão Criar Apontamento."""
            cor_prio = {"Severa / Imediata":"#E74C3C","Importante / Programada":"#F39C12","Observação":"#F1C40F"}.get(prio,"#E74C3C")
            row = ctk.CTkFrame(log_frame, corner_radius=6,
                               fg_color=("white","gray18"), border_width=1,
                               border_color=(cor_prio,cor_prio))
            row.pack(fill="x", pady=3, padx=2)
            txt_f = ctk.CTkFrame(row, fg_color="transparent")
            txt_f.pack(side="left", fill="both", expand=True, padx=(8,4), pady=4)
            ctk.CTkLabel(txt_f,
                         text=f"{'🔴' if prio=='Crítica' else '🟠' if prio=='Média' else '🟡'} {titulo}",
                         anchor="w", font=ctk.CTkFont(weight="bold", size=11),
                         text_color=cor_prio).pack(anchor="w")
            ctk.CTkLabel(txt_f, text=descricao, anchor="w", justify="left",
                         wraplength=360, font=ctk.CTkFont(size=10),
                         text_color=("gray20","gray75")).pack(anchor="w", pady=(2,0))
            ctk.CTkLabel(txt_f, text=f"Tipo: {tipo}",
                         font=ctk.CTkFont(size=9), text_color="gray").pack(anchor="w")

            def criar_apt(t=titulo, d=descricao, p=prio, tp=tipo, dc=disc):
                cid = self.mapa_arquivos.get(dc, self.camada_fundo_id)
                hoje = __import__("datetime").datetime.now().strftime("%d/%m/%Y")
                num = self.contadores_disciplina.get(dc, 1)
                self.contadores_disciplina[dc] = num + 1
                nid = f"{dc[:3].upper()}-{num}"
                prio_fmt = {"Severa / Imediata":"🔴 Severa / Imediata","Importante / Programada":"🟠 Importante / Programada","Observação":"🟡 Observação / Atenção"}.get(p, "🟠 Importante / Programada")
                issue = {
                    'id': nid, 'id_num': num, 'titulo': t, 'descricao': d,
                    'prioridade': prio_fmt, 'tipo': tp, 'disciplina': dc,
                    'camada_id': cid, 'pontos': [], 'imagens': [],
                    'status': 'Em aberto', 'visibilidade': 'Coordenação',
                    'data_criacao': hoje,
                    'participantes': {dc: {'nivel':'Pendência','emails':'','prazo':'','conclusao':''}},
                    'log': [{'data': hoje, 'texto': 'Criado via Análise IA (Gemini).', 'tipo': 'sistema'}],
                    'drawings': [], '_ia_gerado': True
                }
                self.lista_issues.append(issue)
                self.marcar_alterado()
                self.atualizar_painel_issues()
                row.configure(fg_color=("#D5F5E3","#1A3A2A"), border_color=("#27AE60","#27AE60"))
                btn_criar.configure(text="✅ Criado", state="disabled",
                                    fg_color="#27AE60", hover_color="#27AE60")

            btn_criar = ctk.CTkButton(row, text="📍 Criar", width=65, height=50,
                                      fg_color=("#2980B9","#1A5276"),
                                      hover_color=("#2471A3","#154360"),
                                      font=ctk.CTkFont(size=10, weight="bold"),
                                      command=criar_apt)
            btn_criar.pack(side="right", padx=(4,8), pady=4)
            log_frame._parent_canvas.yview_moveto(1.0)
            # Persiste no log da sessão (por disciplina)
            disc_log = cm_disc.get() if 'cm_disc' in dir() else self.disciplina_ativa or ''
            if disc_log not in self.logs_analise_ia:
                self.logs_analise_ia[disc_log] = []
            self.logs_analise_ia[disc_log].append({
                'titulo': titulo, 'descricao': descricao,
                'prio': prio, 'tipo': tipo, 'disc': disc
            })

        def _restaurar_log(disc):
            """Exibe entradas do log anterior para a disciplina."""
            for w in log_frame.winfo_children(): w.destroy()
            entradas = self.logs_analise_ia.get(disc, [])
            if entradas:
                _add_log_text(f"── Log anterior ({len(entradas)} conflito(s)) ──",
                              ("#8E44AD","#8E44AD"))
                for e in entradas:
                    _add_log_conflito(e['titulo'], e['descricao'],
                                      e['prio'], e['tipo'], e['disc'])
            else:
                _add_log_text("Nenhuma análise anterior para esta disciplina.",
                              ("gray50","gray50"))

        # Carrega log ao abrir a janela
        ji.after(100, lambda: _restaurar_log(cm_disc.get()))
        # Atualiza log ao mudar disciplina
        cm_disc.configure(command=lambda v: _restaurar_log(v))

        def disparar():
            if state['running']: return
            state['running'] = True
            btn_iniciar.configure(state="disabled", text="⏳ Analisando...")
            pb.start()
            # Limpa log e inicia nova análise
            for w in log_frame.winfo_children(): w.destroy()
            disc     = cm_disc.get()
            focos    = {k: bool(v.get()) for k, v in checks.items()}
            ctx_extra = tb_ctx.get("1.0","end-1c").strip()
            lbl_status.configure(text="Preparando dados DXF...", text_color="#2980B9")
            ji.update()
            self._stream_analise_ia(
                ji, disc, focos, ctx_extra, lbl_status, btn_iniciar, pb,
                _add_log_text, _add_log_conflito, state)

        btn_iniciar.configure(command=disparar)


    def abrir_menu_exportar(self):
        je = ctk.CTkToplevel(self); je.title("Exportar Relatório e Modelos"); self._centrar_janela(je, 450, 700); je.attributes("-topmost",True)
        ctk.CTkLabel(je, text="📊 Motor de Exportação", font=ctk.CTkFont(size=20,weight="bold")).pack(pady=(15,5))
        lbl_cnt = ctk.CTkLabel(je, text="0 apontamentos selecionados", text_color="#2980B9", font=ctk.CTkFont(weight="bold")); lbl_cnt.pack(pady=(0,10))
        ff = ctk.CTkFrame(je, fg_color=("gray90","gray15"), corner_radius=8); ff.pack(fill="x",padx=20,pady=5,ipadx=10,ipady=10)
        ctk.CTkLabel(ff, text="Filtros Atuais:", font=ctk.CTkFont(size=12,weight="bold")).pack(anchor="w",pady=(0,5))
        fv = self.filtros_ativos
        def _fmt_sel(s):
            return ", ".join(sorted(s)) if s else "Todos"
        c1=ctk.CTkFrame(ff,fg_color="transparent"); c1.pack(fill="x")
        ctk.CTkLabel(c1,text="Status:",width=70,anchor="w").pack(side="left")
        ctk.CTkLabel(c1,text=_fmt_sel(fv.get('status',set())),
                     text_color=("gray20","gray80"),anchor="w").pack(side="left",padx=5)
        c2=ctk.CTkFrame(ff,fg_color="transparent"); c2.pack(fill="x",pady=3)
        ctk.CTkLabel(c2,text="Disciplina:",width=70,anchor="w").pack(side="left")
        ctk.CTkLabel(c2,text=_fmt_sel(fv.get('disciplina',set())),
                     text_color=("gray20","gray80"),anchor="w").pack(side="left",padx=5)
        c2b=ctk.CTkFrame(ff,fg_color="transparent"); c2b.pack(fill="x",pady=3)
        ctk.CTkLabel(c2b,text="Criticidade:",width=70,anchor="w").pack(side="left")
        ctk.CTkLabel(c2b,text=_fmt_sel(fv.get('criticidade',set())),
                     text_color=("gray20","gray80"),anchor="w").pack(side="left",padx=5)
        # variáveis dummy para manter compatibilidade com o restante do código de exportação
        class _FakeCombo:
            def __init__(self,val): self._v=val
            def get(self): return self._v
        cb_s = _FakeCombo("Todos"); cb_d = _FakeCombo("Todas")
        fo2=ctk.CTkFrame(je,fg_color=("gray90","gray15"),corner_radius=8); fo2.pack(fill="x",padx=20,pady=10,ipadx=10,ipady=10)
        ctk.CTkLabel(fo2,text="Opções do Relatório (PDF):",font=ctk.CTkFont(size=12,weight="bold")).pack(anchor="w",pady=(0,5))
        vpr=ctk.IntVar(value=1); ctk.CTkCheckBox(fo2,text="Incluir Prints (Imagens)",variable=vpr).pack(anchor="w",pady=2)
        vtm=ctk.StringVar(value="Original"); ct2=ctk.CTkFrame(fo2,fg_color="transparent"); ct2.pack(fill="x",pady=2,padx=20)
        ctk.CTkRadioButton(ct2,text="Tam. Original",variable=vtm,value="Original").pack(side="left")
        ctk.CTkRadioButton(ct2,text="Reduzido (-30%)",variable=vtm,value="Reduzido").pack(side="left",padx=10)
        vlg2=ctk.IntVar(value=1); ctk.CTkCheckBox(fo2,text="Incluir Comentários e Histórico (Log)",variable=vlg2).pack(anchor="w",pady=5)
        flg=ctk.CTkFrame(fo2,fg_color="transparent"); flg.pack(fill="x",pady=(10,2))
        ctk.CTkLabel(flg,text="Capa:").pack(side="left")
        vlo=ctk.StringVar(value=""); lbl_lo=ctk.CTkLabel(flg,text="Nenhuma logo selecionada",text_color="gray",width=150,anchor="w")
        brlo=ctk.CTkButton(flg,text="❌",width=28,fg_color="#E74C3C",hover_color="#C0392B")
        def rem_lo(): vlo.set(""); lbl_lo.configure(text="Nenhuma logo selecionada",text_color="gray"); brlo.pack_forget()
        brlo.configure(command=rem_lo)
        def sel_lo():
            je.attributes("-topmost",False); p=filedialog.askopenfilename(title="Selecione a Logo",filetypes=[("Imagens","*.png *.jpg *.jpeg")],parent=je); je.attributes("-topmost",True)
            if p: vlo.set(p); lbl_lo.configure(text=os.path.basename(p),text_color="#2ecc71"); brlo.pack(side="left",padx=5)
        ctk.CTkButton(flg,text="📁 Selecionar Logo",width=120,fg_color="gray",command=sel_lo).pack(side="left",padx=10); lbl_lo.pack(side="left",padx=5)

        def get_lista():
            le=[]; stat=cb_s.get(); disc=cb_d.get()
            for iss in self.lista_issues:
                if iss.get('visibilidade')=='Coordenação': continue
                if stat not in ['Todos','Atrasados'] and iss['status']!=stat: continue
                ia=any(self.check_is_atrasado(p['prazo'],p['conclusao']) for p in iss['participantes'].values()) if iss['status']!='Resolvido' else False
                if stat=='Atrasados' and not ia: continue
                if disc!='Todas' and disc not in iss['participantes'] and disc!=iss['disciplina']: continue
                le.append(iss)
            return le

        def upd_cnt(*a): lbl_cnt.configure(text=f"{len(get_lista())} apontamentos selecionados (Públicos)")
        cb_s.configure(command=upd_cnt); cb_d.configure(command=upd_cnt); upd_cnt()
        bts=ctk.CTkFrame(je,fg_color="transparent"); bts.pack(fill="both",expand=True,padx=20,pady=10)

        def gerar_pdf():
            if not HAS_REPORTLAB: messagebox.showerror("Biblioteca Faltando","Instale: pip install reportlab",parent=je); return
            ies=get_lista()
            if not ies: return messagebox.showwarning("Vazio","Nenhum apontamento para exportar.",parent=je)
            je.attributes("-topmost",False); cp2=filedialog.asksaveasfilename(defaultextension=".pdf",filetypes=[("Documento PDF","*.pdf")],title="Salvar Relatório PDF"); je.attributes("-topmost",True)
            if not cp2: return
            try:
                doc=SimpleDocTemplate(cp2,pagesize=A4,rightMargin=40,leftMargin=40,topMargin=40,bottomMargin=40)
                story=[]; styles=getSampleStyleSheet(); tmp_del=[]
                tc=ParagraphStyle('Capa',parent=styles['Title'],fontSize=24,spaceAfter=20)
                sc2=ParagraphStyle('Sub',parent=styles['Normal'],fontSize=16,alignment=1,spaceAfter=10)
                ic2=ParagraphStyle('Info',parent=styles['Normal'],fontSize=12,alignment=1,spaceAfter=30,textColor=colors.gray)
                ti=ParagraphStyle('Issue',parent=styles['Heading2'],fontSize=16,spaceBefore=20,spaceAfter=10,textColor=colors.HexColor("#2980B9"))
                tb2=ParagraphStyle('Bold',parent=styles['Normal'],fontSize=12,fontName='Helvetica-Bold',spaceBefore=10,spaceAfter=5)
                tn=ParagraphStyle('Norm',parent=styles['Normal'],fontSize=11,spaceAfter=5)
                tp2=ParagraphStyle('Peq',parent=styles['Normal'],fontSize=10,textColor=colors.dimgray)
                story.append(Spacer(1,50))
                lp2=vlo.get()
                if lp2 and os.path.exists(lp2):
                    try:
                        with Image.open(lp2) as pi: w2,h2=pi.size
                        dw=150; dh=dw*(h2/float(w2) if w2 else 1)
                        story.append(RLImage(lp2,width=dw,height=dh)); story.append(Spacer(1,20))
                    except: pass
                story.append(Paragraph(self.meta_empreendimento.upper(),tc)); story.append(Paragraph(f"Etapa: {self.meta_etapa}",sc2)); story.append(Paragraph(f"Análise: {self.meta_tipo_analise}",sc2))
                story.append(Spacer(1,100)); story.append(Paragraph(f"Analista Responsável: {self.meta_analista}",ic2)); story.append(PageBreak())
                for iss in ies:
                    tit=iss['titulo'].replace('<','&lt;').replace('>','&gt;')
                    story.append(Paragraph(f"<b>Apontamento {iss['id']}</b>",ti)); story.append(Paragraph(tit,tn))
                    story.append(Paragraph(f"<b>Status:</b> {iss['status']} | <b>Prioridade:</b> {iss['prioridade']} | <b>Tipo:</b> {iss['tipo']}",tn))
                    story.append(Paragraph(f"<b>Criado em:</b> {iss['data_criacao']}",tn)); story.append(Spacer(1,10))
                    if iss['descricao']: story.append(Paragraph("Descrição:",tb2)); story.append(Paragraph(iss['descricao'].replace('\n','<br/>').replace('<','&lt;').replace('>','&gt;'),tn)); story.append(Spacer(1,10))
                    story.append(Paragraph("Participantes e Prazos:",tb2))
                    for d2,p2 in iss['participantes'].items(): story.append(Paragraph(f"• {d2} ({p2['nivel']}) | Prazo: {p2['prazo']} | Conclusão: {p2['conclusao']}",tn))
                    story.append(Spacer(1,15))
                    if vpr.get()==1 and iss.get('imagens'):
                        story.append(Paragraph("Anexos (Prints):",tb2)); lm2=400 if vtm.get()=="Original" else 250
                        for img_obj in iss['imagens']:
                            with tempfile.NamedTemporaryFile(delete=False,suffix=".png") as tmp: img_obj.save(tmp.name,format="PNG"); tp3=tmp.name
                            tmp_del.append(tp3)
                            try:
                                with Image.open(tp3) as pi: w2,h2=pi.size
                                asp=h2/float(w2) if w2 else 1; dw=min(w2,lm2); dh=dw*asp
                                if dh>650: dh=650; dw=dh/asp
                                story.append(RLImage(tp3,width=dw,height=dh)); story.append(Spacer(1,10))
                            except Exception as e3: print(f"Erro anexo: {e3}")
                    if vlg2.get()==1 and iss.get('log'):
                        story.append(Paragraph("Histórico:",tb2))
                        for lg in iss['log']: story.append(Paragraph(f"[{lg['data']}] {lg['texto'].replace('<','&lt;')}",tp2))
                    story.append(Spacer(1,20)); story.append(PageBreak())
                discs=set(iss['disciplina'] for iss in ies); dfo=self.disciplina_ativa; ld2=list(discs)
                def cap(lista,sr):
                    if not lista:
                        try:
                            doc.build(sr)
                            if dfo: self.menu_arquivo_alvo.set(dfo); self.focar_disciplina(dfo)
                            messagebox.showinfo("Sucesso","Relatório PDF gerado com sucesso!",parent=je); je.destroy()
                        except Exception as e3: messagebox.showerror("Erro Crítico",f"Erro:\n{traceback.format_exc()}",parent=je)
                        finally:
                            for f2 in tmp_del:
                                try: os.remove(f2)
                                except: pass
                        return
                    disc=lista.pop(0); self.menu_arquivo_alvo.set(disc); self.focar_disciplina(disc); self.update()
                    def _cap():
                        try:
                            rx=self.desenho_canvas.winfo_rootx(); ry=self.desenho_canvas.winfo_rooty()
                            rw=self.desenho_canvas.winfo_width(); rh=self.desenho_canvas.winfo_height()
                            ip=ImageGrab.grab(bbox=(rx,ry,rx+rw,ry+rh))
                            sr.append(Paragraph(f"Mapa Geral - Foco: {disc}",ti)); sr.append(Spacer(1,10))
                            with tempfile.NamedTemporaryFile(delete=False,suffix=".png") as tmp: ip.save(tmp.name,format="PNG"); tp3=tmp.name
                            tmp_del.append(tp3)
                            with Image.open(tp3) as pi: w2,h2=pi.size
                            asp=h2/float(w2) if w2 else 1; dw=480; dh=dw*asp
                            if dh>650: dh=650; dw=dh/asp
                            sr.append(RLImage(tp3,width=dw,height=dh)); sr.append(PageBreak())
                        except Exception as e3: print(f"Erro prancha {disc}: {e3}")
                        cap(lista,sr)
                    self.after(600,_cap)
                if discs: cap(ld2,story)
                else:
                    try: doc.build(story); messagebox.showinfo("Sucesso","Relatório PDF gerado com sucesso!",parent=je); je.destroy()
                    except Exception as e3: messagebox.showerror("Erro Crítico",f"Erro:\n{traceback.format_exc()}",parent=je)
                    finally:
                        for f2 in tmp_del:
                            try: os.remove(f2)
                            except: pass
            except Exception as e3: messagebox.showerror("Erro Crítico",f"Ocorreu um erro gerando o PDF.\n\n{traceback.format_exc()}",parent=je)

        def gerar_excel():
            if not HAS_OPENPYXL: messagebox.showerror("Biblioteca Faltando","Instale: pip install openpyxl",parent=je); return
            ies=get_lista()
            if not ies: return messagebox.showwarning("Vazio","Nenhum apontamento para exportar.",parent=je)
            je.attributes("-topmost",False); cp2=filedialog.asksaveasfilename(defaultextension=".xlsx",filetypes=[("Planilha Excel","*.xlsx")]); je.attributes("-topmost",True)
            if not cp2: return
            try:
                wb=openpyxl.Workbook(); ws=wb.active; ws.title="Apontamentos"
                ws.append(["ID","Título","Status","Prioridade","Tipo","Data Criação","Disciplinas","Prazos / Status"])
                for iss in ies:
                    ws.append([iss['id'],iss['titulo'],iss['status'],iss['prioridade'],iss['tipo'],iss['data_criacao'],
                                ", ".join(iss['participantes'].keys()),
                                " | ".join([f"{d2}: {p2['prazo']} (Conc: {p2['conclusao']})" for d2,p2 in iss['participantes'].items()])])
                wb.save(cp2); messagebox.showinfo("Sucesso","Tabela Excel exportada com sucesso!",parent=je); je.destroy()
            except Exception as e3: messagebox.showerror("Erro",f"Erro ao gerar Excel: {e3}",parent=je)

        def gerar_bcf():
            ies=get_lista()
            if not ies: return messagebox.showwarning("Vazio","Nenhum apontamento para exportar.",parent=je)
            je.attributes("-topmost",False); cp2=filedialog.asksaveasfilename(defaultextension=".bcfzip",filetypes=[("Arquivo BCF","*.bcfzip")]); je.attributes("-topmost",True)
            if not cp2: return
            try:
                with zipfile.ZipFile(cp2,'w') as bz:
                    bz.writestr('bcf.version','<?xml version="1.0" encoding="UTF-8"?><Version VersionId="2.1"/>')
                    for iss in ies:
                        tid=str(uuid.uuid4()); mk=ET.Element("Markup")
                        tp4=ET.SubElement(mk,"Topic",Guid=tid,TopicType=iss['tipo'],TopicStatus=iss['status'])
                        ET.SubElement(tp4,"Title").text=iss['titulo']; ET.SubElement(tp4,"Priority").text=iss['prioridade']
                        ET.SubElement(tp4,"CreationDate").text=datetime.now().isoformat(); ET.SubElement(tp4,"CreationAuthor").text=self.meta_analista
                        ET.SubElement(tp4,"Description").text=iss['descricao']
                        bz.writestr(f'{tid}/markup.bcfv',ET.tostring(mk,encoding='utf-8',method='xml').decode())
                        if iss.get('imagens'):
                            with tempfile.NamedTemporaryFile(delete=False,suffix=".png") as tmp: iss['imagens'][0].save(tmp.name,format="PNG"); tp3=tmp.name
                            bz.write(tp3,f'{tid}/snapshot.png'); os.remove(tp3)
                messagebox.showinfo("Sucesso","Arquivo BCF gerado com sucesso!",parent=je); je.destroy()
            except Exception as e3: messagebox.showerror("Erro",f"Erro ao gerar BCF: {e3}",parent=je)

        ctk.CTkButton(bts,text="📄 Gerar Relatório PDF",fg_color="#E74C3C",hover_color="#C0392B",command=gerar_pdf).pack(fill="x",pady=5)
        ctk.CTkButton(bts,text="📊 Tabela Excel (.xlsx)",fg_color="#27AE60",hover_color="#229954",command=gerar_excel).pack(fill="x",pady=5)
        ctk.CTkButton(bts,text="🏗️ Arquivo BCF (BIM)",fg_color="#F39C12",hover_color="#D68910",command=gerar_bcf).pack(fill="x",pady=5)


